                  { value: "draft", label: l("Draft", "Borrador") },
                  { value: "open", label: l("Open", "Pendiente") },
                  { value: "paid", label: l("Paid", "Pagada") },
                  { value: "overdue", label: l("Overdue", "Vencida") },
                  { value: "void", label: l("Void", "Anulada") },
                ]}
              />
              <Select
                aria-label={l(
                  "Filter invoice currency",
