        </div>
        <div className="grid gap-3 p-5">
          {draft.images.length > 1 && (
            <div
              role="group"
              aria-label={l("Preview images", "Imágenes de vista previa")}
              className="flex flex-wrap gap-2"
            >
              {draft.images.map((thumbnail, index) => (
                <button
                  type="button"
                  key={thumbnail.id}
                  aria-label={l(
                    `Preview image ${index + 1}`,
