"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { useWorkspace } from "@/components/workspace-provider";
import { createCommerceSeed } from "@/demo/commerce-data";
import {
  CommerceError,
  buildOrder,
  commerceInvoiceSchema,
  commerceOrderSchema,
  commerceProductSchema,
  newInvoiceSchema,
  type CommerceAction,
  type CommerceAdapter,
  type CommerceContextValue,
  type CommerceProviderIdentity,
  type CommerceScope,
  type CommerceSnapshot,
} from "@/lib/commerce";
import {
  COMMERCE_STORAGE_PREFIX,
  commercePlans,
  completeMockCheckout,
  parseCommerceSnapshot,
  upsertCommerceProduct,
} from "@/lib/commerce-state";
import { parseStripeAction } from "@/lib/stripe-commerce-adapter";
import {
  parseProviderCommerceAction,
  parseProviderCommerceSnapshot,
} from "@/lib/provider-commerce-adapter";

const Context = createContext<CommerceContextValue | null>(null);
type Session = {
  workspaceId: string;
  adapter?: CommerceAdapter;
  snapshot: CommerceSnapshot;
  ready: boolean;
};
const now = () => new Date().toISOString();
const identifier = (prefix: string) => `${prefix}-${crypto.randomUUID()}`;
const storageKey = (workspaceId: string) =>
  `${COMMERCE_STORAGE_PREFIX}${encodeURIComponent(workspaceId)}`;
function asCommerceError(error: unknown) {
  return error instanceof CommerceError
    ? error
    : new CommerceError(
        "provider",
        "The operation could not be completed. Try again.",
      );
}

/**
 * The default provider is an isolated, persistent demo. Supply an adapter from
 * a consumer's client wrapper to connect these views to their own backend.
 */
export function CommerceProvider({
  children,
  adapter,
  demoProvider,
}: {
  children: ReactNode;
  adapter?: CommerceAdapter;
  /** Display identity for a local demo; never selects a connected account. */
  demoProvider?: CommerceProviderIdentity;
}) {
  const workspace = useWorkspace();
  const workspaceId = workspace.workspaceId;
  const mode = adapter?.mode ?? "mock";
  const provider = adapter
    ? (adapter.provider ?? {
        id: mode === "stripe" ? "stripe" : "commerce",
        label: mode === "stripe" ? "Stripe" : "Commerce",
      })
    : demoProvider;
  const initial = useMemo(() => createCommerceSeed(), []);
  const [session, setSession] = useState<Session>({
    workspaceId,
    adapter,
    snapshot: initial,
    ready: false,
  });
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<CommerceError | null>(null);
  const [persistenceError, setPersistenceError] =
    useState<CommerceContextValue["persistenceError"]>(null);
  const sessionRef = useRef(session);
  const workspaceIdRef = useRef(workspaceId);
  const adapterRef = useRef(adapter);
  const generationRef = useRef(0);
  const operationRef = useRef<AbortController | null>(null);
  const busyRef = useRef(false);
  const cacheRef = useRef(new Map<string, CommerceSnapshot>());
  const permissionsRef = useRef({ write: false, billing: false, ready: false });
  const canWrite = workspace.role !== "viewer";
  const canManageBilling =
    workspace.role === "owner" || workspace.role === "admin";
  useLayoutEffect(() => {
    if (adapterRef.current !== adapter) {
      operationRef.current?.abort();
      generationRef.current += 1;
      busyRef.current = false;
      adapterRef.current = adapter;
    }
    workspaceIdRef.current = workspaceId;
    permissionsRef.current = {
      write: canWrite,
      billing: canManageBilling,
      ready: workspace.ready,
    };
  }, [adapter, workspaceId, canWrite, canManageBilling, workspace.ready]);

  const persist = useCallback((scopeId: string, snapshot: CommerceSnapshot) => {
    cacheRef.current.set(scopeId, snapshot);
    try {
      localStorage.setItem(storageKey(scopeId), JSON.stringify(snapshot));
      setPersistenceError(null);
    } catch {
      // Quota/privacy failures preserve the working in-memory session.
      setPersistenceError("write");
    }
  }, []);

  const load = useCallback(async () => {
    if (!permissionsRef.current.ready) return;
    const scopeId = workspaceId;
    operationRef.current?.abort();
    const controller = new AbortController();
    operationRef.current = controller;
    const generation = ++generationRef.current;
    busyRef.current = true;
    setBusy("load");
    setError(null);
    setPersistenceError(null);
    const pending: Session = {
      workspaceId: scopeId,
      adapter,
      snapshot: adapter
        ? { ...createCommerceSeed(), products: [], orders: [], invoices: [] }
        : (cacheRef.current.get(scopeId) ?? createCommerceSeed()),
      ready: false,
    };
    sessionRef.current = pending;
    setSession(pending);
    const current = () =>
      !controller.signal.aborted &&
      generationRef.current === generation &&
      workspaceIdRef.current === scopeId &&
      adapterRef.current === adapter;
    try {
      let snapshot = pending.snapshot;
      if (adapter) {
        const response = await adapter.load({
          workspaceId: scopeId,
          signal: controller.signal,
        });
        const parsed =
          adapter.mode === "provider"
            ? parseProviderCommerceSnapshot(response)
            : parseCommerceSnapshot(response);
        if (!parsed)
          throw new CommerceError(
            "provider",
            "The backend returned an invalid commerce response.",
          );
        snapshot = parsed;
      } else if (!cacheRef.current.has(scopeId)) {
        try {
          const stored = localStorage.getItem(storageKey(scopeId));
          if (stored) {
            const parsed = parseCommerceSnapshot(JSON.parse(stored));
            if (parsed) snapshot = parsed;
            else if (current()) setPersistenceError("invalid");
          }
        } catch {
          if (current()) setPersistenceError("read");
        }
      }
      if (!current()) return;
      if (!adapter) cacheRef.current.set(scopeId, snapshot);
      const next: Session = {
        workspaceId: scopeId,
        adapter,
        snapshot,
        ready: true,
      };
      sessionRef.current = next;
      setSession(next);
    } catch (cause) {
      if (current()) {
        const failure = asCommerceError(cause);
        setError(failure);
        throw failure;
      }
    } finally {
      if (current()) {
        busyRef.current = false;
        operationRef.current = null;
        setBusy(null);
      }
    }
  }, [adapter, workspaceId]);

  useEffect(() => {
    if (workspace.ready) void load().catch(() => {});
    return () => {
      operationRef.current?.abort();
      generationRef.current += 1;
      busyRef.current = false;
    };
  }, [load, workspace.ready]);

  useEffect(() => {
    if (adapter) return;
    const receive = (event: StorageEvent) => {
      if (
        workspaceIdRef.current !== workspaceId ||
        event.key !== storageKey(workspaceId) ||
        busyRef.current
      )
        return;
      try {
        const incoming = event.newValue
          ? parseCommerceSnapshot(JSON.parse(event.newValue))
          : createCommerceSeed();
        if (!incoming) {
          setPersistenceError("invalid");
          return;
        }
        cacheRef.current.set(workspaceId, incoming);
        const next = { workspaceId, snapshot: incoming, ready: true };
        sessionRef.current = next;
        setSession(next);
        setPersistenceError(null);
      } catch {
        setPersistenceError("read");
      }
    };
    window.addEventListener("storage", receive);
    return () => window.removeEventListener("storage", receive);
  }, [adapter, workspaceId]);

  const perform = useCallback(
    async <T,>(
      label: string,
      permission: "write" | "billing",
      operation: (
        snapshot: CommerceSnapshot,
        scope: CommerceScope,
      ) => Promise<{ result: T; next?: CommerceSnapshot }>,
    ): Promise<T> => {
      const currentSession = sessionRef.current;
      if (
        !permissionsRef.current.ready ||
        !currentSession.ready ||
        currentSession.workspaceId !== workspaceIdRef.current ||
        currentSession.adapter !== adapter
      )
        throw new CommerceError(
          "unavailable",
          "Wait for the workspace to finish loading.",
        );
      if (!permissionsRef.current[permission]) {
        throw new CommerceError(
          "forbidden",
          "Your workspace role cannot perform this action.",
        );
      }
      if (busyRef.current)
        throw new CommerceError(
          "conflict",
          "Another operation is still in progress.",
        );
      const scopeId = currentSession.workspaceId;
      const controller = new AbortController();
      const generation = generationRef.current;
      operationRef.current = controller;
      busyRef.current = true;
      setBusy(label);
      setError(null);
      const current = () =>
        !controller.signal.aborted &&
        generationRef.current === generation &&
        workspaceIdRef.current === scopeId &&
        adapterRef.current === adapter;
      try {
        const { result, next } = await operation(currentSession.snapshot, {
          workspaceId: scopeId,
          signal: controller.signal,
        });
        if (!current())
          throw new CommerceError(
            "conflict",
            "The workspace changed. Review the current data.",
          );
        if (next) {
          const parsed =
            adapter?.mode === "provider"
              ? parseProviderCommerceSnapshot(next)
              : parseCommerceSnapshot(next);
          if (!parsed)
            throw new CommerceError(
              "validation",
              "The update contains invalid commerce data.",
            );
          const updated: Session = {
            workspaceId: scopeId,
            adapter,
            snapshot: parsed,
            ready: true,
          };
          sessionRef.current = updated;
          setSession(updated);
          if (!adapter) persist(scopeId, parsed);
        }
        return result;
      } catch (cause) {
        const failure = asCommerceError(cause);
        if (current()) setError(failure);
        throw failure;
      } finally {
        if (current()) {
          busyRef.current = false;
          operationRef.current = null;
          setBusy(null);
        }
      }
    },
    [adapter, persist],
  );

  const saveProduct = useCallback<CommerceContextValue["saveProduct"]>(
    (candidate) =>
      perform(`product:${candidate.id}`, "write", async (snapshot, scope) => {
        const parsed = commerceProductSchema.safeParse(candidate);
        if (!parsed.success)
          throw new CommerceError("validation", "Check the product fields.");
        const response = adapter
          ? await adapter.saveProduct(parsed.data, scope)
          : parsed.data;
        const validated = commerceProductSchema.safeParse(response);
        if (!validated.success || validated.data.id !== candidate.id) {
          throw new CommerceError(
            "provider",
            "The backend returned an invalid product.",
          );
        }
        const next = upsertCommerceProduct(
          snapshot,
          validated.data,
          adapter ? validated.data.updatedAt : now(),
        );
        return {
          result: next.products.find((item) => item.id === candidate.id)!,
          next,
        };
      }),
    [adapter, perform],
  );

  const changeProduct = useCallback(
    (id: string, action: "archive" | "sync") =>
      perform(`product:${id}`, "write", async (snapshot, scope) => {
        const product = snapshot.products.find((item) => item.id === id);
        if (!product)
          throw new CommerceError(
            "unavailable",
            "The product is no longer available.",
          );
        const response = adapter
          ? await (action === "archive"
              ? adapter.archiveProduct(id, scope)
              : adapter.syncProduct(id, scope))
          : action === "archive"
            ? { ...product, status: "archived" as const }
            : {
                ...product,
                stripeProductId: product.stripeProductId ?? `prod_demo_${id}`,
                stripePriceId:
                  product.stripePriceId ??
                  `price_demo_${crypto.randomUUID().replaceAll("-", "")}`,
              };
        const validated = commerceProductSchema.safeParse(response);
        if (!validated.success || validated.data.id !== id) {
          throw new CommerceError(
            "provider",
            "The backend returned an invalid product.",
          );
        }
        const next = upsertCommerceProduct(
          snapshot,
          validated.data,
          adapter ? validated.data.updatedAt : now(),
        );
        return { result: next.products.find((item) => item.id === id)!, next };
      }),
    [adapter, perform],
  );
  const archiveProduct = useCallback<CommerceContextValue["archiveProduct"]>(
    (id) => changeProduct(id, "archive"),
    [changeProduct],
  );
  const syncProduct = useCallback<CommerceContextValue["syncProduct"]>(
    (id) => changeProduct(id, "sync"),
    [changeProduct],
  );

  const createOrder = useCallback<CommerceContextValue["createOrder"]>(
    (input) =>
      perform("order:create", "write", async (snapshot, scope) => {
        if (snapshot.orders.length >= 1000)
          throw new CommerceError("conflict", "The demo order list is full.");
        const preview = buildOrder(
          input,
          snapshot.products,
          identifier("ord"),
          now(),
        );
        const response = adapter
          ? await adapter.createOrder(input, scope)
          : preview;
        const validated = commerceOrderSchema.safeParse(response);
        if (
          !validated.success ||
          snapshot.orders.some((item) => item.id === validated.data.id)
        ) {
          throw new CommerceError(
            "provider",
            "The backend returned an invalid order.",
          );
        }
        return {
          result: validated.data,
          next: { ...snapshot, orders: [validated.data, ...snapshot.orders] },
        };
      }),
    [adapter, perform],
  );

  const updateOrderStatus = useCallback<
    CommerceContextValue["updateOrderStatus"]
  >(
    (id, status) =>
      perform(`order:${id}`, "write", async (snapshot, scope) => {
        const order = snapshot.orders.find((item) => item.id === id);
        if (!order)
          throw new CommerceError(
            "unavailable",
            "The order is no longer available.",
          );
        if (order.status === "cancelled")
          throw new CommerceError(
            "conflict",
            "A cancelled order cannot be reopened.",
          );
        if (
          !["processing", "shipped", "delivered", "cancelled"].includes(status)
        ) {
          throw new CommerceError(
            "validation",
            "Choose an available order status.",
          );
        }
        if (
          (status === "shipped" || status === "delivered") &&
          order.paymentStatus !== "paid"
        ) {
          throw new CommerceError(
            "conflict",
            "An unpaid order cannot be shipped.",
          );
        }
        const response = adapter
          ? await adapter.updateOrderStatus(id, status, scope)
          : { ...order, status };
        const validated = commerceOrderSchema.safeParse(response);
        if (!validated.success || validated.data.id !== id)
          throw new CommerceError(
            "provider",
            "The backend returned an invalid order.",
          );
        return {
          result: validated.data,
          next: {
            ...snapshot,
            orders: snapshot.orders.map((item) =>
              item.id === id ? validated.data : item,
            ),
          },
        };
      }),
    [adapter, perform],
  );

  const createInvoice = useCallback<CommerceContextValue["createInvoice"]>(
    (input) =>
      perform("invoice:create", "write", async (snapshot, scope) => {
        const parsed = newInvoiceSchema.safeParse(input);
        if (!parsed.success)
          throw new CommerceError("validation", "Check the invoice fields.");
        if (snapshot.invoices.length >= 1000)
          throw new CommerceError("conflict", "The demo invoice list is full.");
        const createdAt = now();
        const response = adapter
          ? await adapter.createInvoice(parsed.data, scope)
          : {
              ...parsed.data,
              id: identifier("inv"),
              number: `INV-${Date.now().toString(36).toUpperCase()}`,
              status: "open" as const,
              issuedAt: createdAt,
            };
        const validated = commerceInvoiceSchema.safeParse(response);
        if (
          !validated.success ||
          snapshot.invoices.some((item) => item.id === validated.data.id)
        ) {
          throw new CommerceError(
            "provider",
            "The backend returned an invalid invoice.",
          );
        }
        return {
          result: validated.data,
          next: {
            ...snapshot,
            invoices: [validated.data, ...snapshot.invoices],
          },
        };
      }),
    [adapter, perform],
  );

  const checkout = useCallback(
    (kind: "order" | "invoice" | "subscription", id: string) =>
      perform(
        `checkout:${id}`,
        kind === "subscription" ? "billing" : "write",
        async (snapshot, scope) => {
          if (kind === "order") {
            const order = snapshot.orders.find((item) => item.id === id);
            if (
              !order ||
              order.status === "cancelled" ||
              !["unpaid", "failed"].includes(order.paymentStatus)
            ) {
              throw new CommerceError(
                "unavailable",
                "This order cannot be paid.",
              );
            }
          } else if (kind === "invoice") {
            const invoice = snapshot.invoices.find((item) => item.id === id);
            if (!invoice || !["open", "overdue"].includes(invoice.status)) {
              throw new CommerceError(
                "unavailable",
                "This invoice cannot be paid.",
              );
            }
          } else if (!commercePlans.some((item) => item.name === id)) {
            throw new CommerceError("validation", "Choose an available plan.");
          }
          const result: CommerceAction = adapter
            ? adapter.mode === "stripe"
              ? parseStripeAction(await adapter.checkout({ kind, id }, scope))
              : parseProviderCommerceAction(
                  await adapter.checkout({ kind, id }, scope),
                  adapter.trustedRedirectOrigins ?? [],
                )
            : { mode: "mock", kind, id };
          return { result };
        },
      ),
    [adapter, perform],
  );
  const checkoutOrder = useCallback<CommerceContextValue["checkoutOrder"]>(
    (id) => checkout("order", id),
    [checkout],
  );
  const payInvoice = useCallback<CommerceContextValue["payInvoice"]>(
    (id) => checkout("invoice", id),
    [checkout],
  );
  const checkoutPlan = useCallback<CommerceContextValue["checkoutPlan"]>(
    (plan) => checkout("subscription", plan),
    [checkout],
  );
  const openPortal = useCallback<CommerceContextValue["openPortal"]>(
    () =>
      perform("portal", "billing", async (_snapshot, scope) => ({
        result: adapter
          ? adapter.mode === "stripe"
            ? parseStripeAction(await adapter.portal(scope))
            : parseProviderCommerceAction(
                await adapter.portal(scope),
                adapter.trustedRedirectOrigins ?? [],
              )
          : { mode: "mock", kind: "portal", id: scope.workspaceId },
      })),
    [adapter, perform],
  );
  const simulateCheckout = useCallback<
    CommerceContextValue["simulateCheckout"]
  >(
    (action, outcome) =>
      perform(
        `simulate:${action.id}`,
        action.kind === "subscription" ? "billing" : "write",
        async (snapshot) => {
          if (adapter)
            throw new CommerceError(
              "forbidden",
              "Payment status is managed by the backend.",
            );
          return {
            result: undefined,
            next: completeMockCheckout(snapshot, action, outcome, now()),
          };
        },
      ),
    [adapter, perform],
  );
  const retryPersistence = useCallback(() => {
    const current = sessionRef.current;
    if (
      !adapter &&
      current.ready &&
      current.workspaceId === workspaceIdRef.current
    ) {
      persist(current.workspaceId, current.snapshot);
    }
  }, [adapter, persist]);

  const sameSession =
    session.workspaceId === workspaceId && session.adapter === adapter;
  const view = sameSession ? session.snapshot : initial;
  const value: CommerceContextValue = {
    ...view,
    ready: workspace.ready && session.ready && sameSession,
    busy,
    mode,
    provider,
    error,
    persistenceError,
    canWrite,
    canManageBilling,
    reload: load,
    retryPersistence,
    saveProduct,
    archiveProduct,
    syncProduct,
    createOrder,
    updateOrderStatus,
    createInvoice,
    checkoutOrder,
    payInvoice,
    checkoutPlan,
    openPortal,
    simulateCheckout,
  };
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

export function useCommerce() {
  const value = useContext(Context);
  if (!value)
    throw new Error("useCommerce must be used inside CommerceProvider.");
  return value;
}

"use client";

import { useEffect, type RefObject } from "react";
import { effectFrameInterval } from "./effect-utils";

export type EffectEnvironment = {
  inView: boolean;
  visible: boolean;
  motion: boolean;
  finePointer: boolean;
};

/** Browser APIs are touched only by effects, never during an SSR render. */
export function watchEffectEnvironment(
  element: HTMLElement,
  notify: (environment: EffectEnvironment) => void,
) {
  const reduced =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)")
      : null;
  const pointer =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(hover: hover) and (pointer: fine)")
      : null;
  const forced =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(forced-colors: active)")
      : null;
  let disposed = false;
  let inView = false;

  const visible = () => {
    if (document.visibilityState === "hidden" || !element.isConnected)
      return false;
    const style = getComputedStyle(element);
    // checkVisibility checks the host box, but its own hidden content can still
    // leave that box visible while suppressing every decorative child.
    if (
      style.visibility === "hidden" ||
      style.visibility === "collapse" ||
      style.opacity === "0" ||
      style.contentVisibility === "hidden"
    )
      return false;
    if (typeof element.checkVisibility === "function") {
      return element.checkVisibility({
        checkOpacity: true,
        checkVisibilityCSS: true,
        contentVisibilityAuto: true,
      });
    }
    if (!element.getClientRects().length) return false;
    for (
      let ancestor: HTMLElement | null = element;
      ancestor;
      ancestor = ancestor.parentElement
    ) {
      const ancestorStyle = getComputedStyle(ancestor);
      if (
        ancestorStyle.opacity === "0" ||
        ancestorStyle.contentVisibility === "hidden"
      )
        return false;
    }
    return true;
  };

  const report = () => {
    if (disposed) return;
    notify({
      inView,
      visible: visible(),
      motion:
        reduced !== null &&
        !reduced.matches &&
        !forced?.matches &&
        (
          element.closest("[data-motion-level]") ?? document.documentElement
        ).getAttribute("data-motion-level") !== "off",
      finePointer: pointer?.matches ?? false,
    });
  };

  const observeMedia = (media: MediaQueryList | null) => {
    if (!media) return () => {};
    if (typeof media.addEventListener === "function") {
      media.addEventListener("change", report);
      return () => media.removeEventListener("change", report);
    }
    media.addListener(report);
    return () => media.removeListener(report);
  };
  const removeReduced = observeMedia(reduced);
  const removePointer = observeMedia(pointer);
  const removeForced = observeMedia(forced);
  document.addEventListener("visibilitychange", report);
  window.addEventListener("aureform:appearance-change", report);
  window.addEventListener("resize", report, { passive: true });

  // Observe only this element's ancestry, not every mutation in the document.
  // Ignore our own pointer variables, which otherwise retrigger the observer.
  const ownStyle = () =>
    Array.from(element.style)
      .filter((name) => !name.startsWith("--afx-"))
      .map(
        (name) =>
          `${name}:${element.style.getPropertyValue(name)}:${element.style.getPropertyPriority(name)}`,
      )
      .join(";");
  let previousStyle = ownStyle();
  const motionObserver =
    typeof MutationObserver !== "undefined"
      ? new MutationObserver((records) => {
          const nextStyle = ownStyle();
          const ownVariablesOnly =
            nextStyle === previousStyle &&
            records.every(
              (record) =>
                record.target === element && record.attributeName === "style",
            );
          previousStyle = nextStyle;
          if (!ownVariablesOnly) report();
        })
      : null;
  for (
    let ancestor: HTMLElement | null = element;
    ancestor;
    ancestor = ancestor.parentElement
  ) {
    motionObserver?.observe(ancestor, {
      attributes: true,
      attributeFilter: [
        "data-motion-level",
        "data-palette",
        "style",
        "class",
        "hidden",
        "open",
        "disabled",
      ],
    });
  }

  let intersection: IntersectionObserver | null = null;
  const measureView = () => {
    const bounds = element.getBoundingClientRect();
    inView =
      bounds.width > 0 &&
      bounds.height > 0 &&
      bounds.bottom > 0 &&
      bounds.right > 0 &&
      bounds.top < window.innerHeight &&
      bounds.left < window.innerWidth;
    report();
  };
  if (typeof IntersectionObserver !== "undefined") {
    intersection = new IntersectionObserver(
      ([entry]) => {
        inView = Boolean(entry?.isIntersecting && entry.intersectionRatio > 0);
        report();
      },
      { threshold: 0 },
    );
    intersection.observe(element);
  } else {
    // Old embedded browsers still pause offscreen without a polyfill.
    window.addEventListener("scroll", measureView, {
      passive: true,
      capture: true,
    });
    window.addEventListener("resize", measureView, { passive: true });
    measureView();
  }
  report();

  return () => {
    disposed = true;
    intersection?.disconnect();
    motionObserver?.disconnect();
    removeReduced();
    removePointer();
    removeForced();
    document.removeEventListener("visibilitychange", report);
    window.removeEventListener("aureform:appearance-change", report);
    window.removeEventListener("resize", report);
    window.removeEventListener("scroll", measureView, true);
    window.removeEventListener("resize", measureView);
  };
}

export function useEffectActivity(ref: RefObject<HTMLElement | null>) {
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const remove = watchEffectEnvironment(element, (environment) => {
      element.dataset.afxMotion =
        environment.motion && environment.visible && environment.inView
          ? "running"
          : "paused";
    });
    return () => {
      remove();
      element.dataset.afxMotion = "paused";
    };
  }, [ref]);
}

const editingTarget =
  'input, textarea, select, [contenteditable]:not([contenteditable="false"]), [data-effect-static]';
const disabledTarget = ':disabled, [aria-disabled="true"], [data-disabled]';

/**
 * One frame-coalesced write per pointer update. Never captures a pointer,
 * cancels an event, changes touch-action, or installs a wheel handler.
 */
export function useEffectPointer(
  ref: RefObject<HTMLElement | null>,
  mode: "spotlight" | "tilt" | "magnetic",
  amount: number,
  limit: number,
) {
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    let environment: EffectEnvironment = {
      inView: false,
      visible: false,
      motion: false,
      finePointer: false,
    };
    let frame = 0;
    let lastWrite = -Infinity;
    let bounds: DOMRect | null = null;
    let point = { x: 0, y: 0 };

    const reset = () => {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      bounds = null;
      element.dataset.afxPointer = "idle";
      element.style.setProperty("--afx-pointer-x", "50%");
      element.style.setProperty("--afx-pointer-y", "35%");
      element.style.setProperty("--afx-rotate-x", "0deg");
      element.style.setProperty("--afx-rotate-y", "0deg");
      element.style.setProperty("--afx-magnetic-x", "0px");
      element.style.setProperty("--afx-magnetic-y", "0px");
    };

    const allowed = () =>
      environment.inView &&
      environment.visible &&
      environment.motion &&
      environment.finePointer &&
      !element.matches(disabledTarget) &&
      // Keep a focused control stationary for keyboard and mixed-input users.
      (mode === "spotlight" || !element.contains(document.activeElement));

    const write = (now: number) => {
      frame = 0;
      if (!allowed() || !bounds || !bounds.width || !bounds.height) {
        reset();
        return;
      }
      if (now - lastWrite < effectFrameInterval) {
        frame = requestAnimationFrame(write);
        return;
      }
      lastWrite = now;
      const x = Math.min(
        1,
        Math.max(0, (point.x - bounds.left) / bounds.width),
      );
      const y = Math.min(
        1,
        Math.max(0, (point.y - bounds.top) / bounds.height),
      );
      element.dataset.afxPointer = "active";
      element.style.setProperty("--afx-pointer-x", `${(x * 100).toFixed(2)}%`);
      element.style.setProperty("--afx-pointer-y", `${(y * 100).toFixed(2)}%`);
      if (mode === "tilt") {
        element.style.setProperty(
          "--afx-rotate-x",
          `${((0.5 - y) * amount * 2).toFixed(2)}deg`,
        );
        element.style.setProperty(
          "--afx-rotate-y",
          `${((x - 0.5) * amount * 2).toFixed(2)}deg`,
        );
      } else if (mode === "magnetic") {
        const dx = Math.min(
          limit,
          Math.max(-limit, (x - 0.5) * bounds.width * amount),
        );
        const dy = Math.min(
          limit,
          Math.max(-limit, (y - 0.5) * bounds.height * amount),
        );
        element.style.setProperty("--afx-magnetic-x", `${dx.toFixed(2)}px`);
        element.style.setProperty("--afx-magnetic-y", `${dy.toFixed(2)}px`);
      }
    };

    const move = (event: PointerEvent) => {
      if (
        !allowed() ||
        event.defaultPrevented ||
        event.buttons !== 0 ||
        !["mouse", "pen"].includes(event.pointerType) ||
        (event.target instanceof Element && event.target.closest(editingTarget))
      ) {
        reset();
        return;
      }
      // A stable entry rectangle prevents feedback from the element's transform.
      bounds ??= element.getBoundingClientRect();
      point = { x: event.clientX, y: event.clientY };
      if (!frame) frame = requestAnimationFrame(write);
    };
    const focus = () => reset();
    const removeEnvironment = watchEffectEnvironment(element, (next) => {
      environment = next;
      element.dataset.afxMotion =
        next.motion && next.inView && next.visible ? "running" : "paused";
      if (!allowed()) reset();
    });

    element.addEventListener("pointerenter", move, { passive: true });
    element.addEventListener("pointermove", move, { passive: true });
    element.addEventListener("pointerleave", reset, { passive: true });
    element.addEventListener("pointercancel", reset, { passive: true });
    element.addEventListener("pointerdown", reset, { passive: true });
    element.addEventListener("focusin", focus);
    window.addEventListener("scroll", reset, { passive: true, capture: true });
    window.addEventListener("resize", reset, { passive: true });

    // Native disabled/loading changes also settle an already active transform.
    const disabledObserver =
      typeof MutationObserver !== "undefined"
        ? new MutationObserver(() => {
            if (element.matches(disabledTarget)) reset();
          })
        : null;
    disabledObserver?.observe(element, {
      attributes: true,
      attributeFilter: ["disabled", "aria-disabled", "data-disabled"],
    });

    return () => {
      removeEnvironment();
      disabledObserver?.disconnect();
      element.removeEventListener("pointerenter", move);
      element.removeEventListener("pointermove", move);
      element.removeEventListener("pointerleave", reset);
      element.removeEventListener("pointercancel", reset);
      element.removeEventListener("pointerdown", reset);
      element.removeEventListener("focusin", focus);
      window.removeEventListener("scroll", reset, true);
      window.removeEventListener("resize", reset);
      reset();
      element.dataset.afxMotion = "paused";
    };
  }, [ref, mode, amount, limit]);
}

"use client";

import {
  Children,
  Fragment,
  cloneElement,
  createElement,
  isValidElement,
  useCallback,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import { cn } from "@/lib/utils";

export type EffectSurfaceProps = HTMLAttributes<HTMLElement> & {
  as?: "div" | "article" | "section";
  /** Apply the effect to one ref-forwarding element, such as an a or button. */
  asChild?: boolean;
  children?: ReactNode;
  ref?: Ref<HTMLElement>;
};

type SurfaceElementProps = HTMLAttributes<HTMLElement> & {
  ref?: Ref<HTMLElement>;
};

export function useComposedEffectRef(
  outerRef?: Ref<HTMLElement>,
  innerRef?: Ref<HTMLElement>,
) {
  return useCallback(
    (node: HTMLElement | null) => {
      const refs = [outerRef, innerRef];
      const cleanups = refs.map((ref) => {
        if (typeof ref === "function") return ref(node);
        if (ref) ref.current = node;
      });
      return () => {
        refs.forEach((ref, index) => {
          const cleanup = cleanups[index];
          if (typeof cleanup === "function") cleanup();
          else if (typeof ref === "function") ref(null);
          else if (ref) ref.current = null;
        });
      };
    },
    [outerRef, innerRef],
  );
}

/**
 * Preserve the child's semantics, handlers and ref. Cards do not acquire a
 * tab stop or a button role simply because they have a decorative effect.
 */
export function EffectSurface({
  as = "div",
  asChild = false,
  children,
  ref,
  ...props
}: Omit<EffectSurfaceProps, "as"> & {
  as?: EffectSurfaceProps["as"] | "button";
  type?: "button" | "submit" | "reset";
  disabled?: boolean;
}) {
  const child = asChild ? Children.only(children) : null;
  if (asChild && (!isValidElement(child) || child.type === Fragment)) {
    throw new Error("An effect with asChild needs one ref-forwarding element.");
  }

  const element = child as ReactElement<SurfaceElementProps> | null;
  const childRef = element?.props.ref;
  const mergedRef = useComposedEffectRef(ref, childRef);

  if (!element) {
    return createElement(as, { ...props, ref: mergedRef }, children);
  }

  const merged: Record<string, unknown> = { ...props, ...element.props };
  for (const key of Object.keys(props)) {
    const outside = (props as Record<string, unknown>)[key];
    const inside = (element.props as Record<string, unknown>)[key];
    if (
      /^on[A-Z]/.test(key) &&
      typeof outside === "function" &&
      typeof inside === "function"
    ) {
      merged[key] = (event: { defaultPrevented?: boolean }) => {
        inside(event);
        if (!event.defaultPrevented) outside(event);
      };
    }
  }
  merged.className = cn(props.className, element.props.className);
  merged.style = { ...props.style, ...element.props.style };
  merged.ref = mergedRef;
  return cloneElement(element, merged);
}

import type { CSSProperties } from "react";

export const defaultEffectColors = ["#8b5cf6", "#22d3ee", "#34d399"] as const;
export const effectFrameRate = 30;
export const effectFrameInterval = 1000 / effectFrameRate;

export type EffectStyle = CSSProperties & {
  [key: `--afx-${string}`]: string | number;
};

export function boundedNumber(
  value: number | undefined,
  min: number,
  max: number,
  fallback: number,
) {
  return Number.isFinite(value)
    ? Math.min(max, Math.max(min, value as number))
    : fallback;
}

/** Missing palette entries retain the original violet/cyan/emerald palette. */
export function effectColors(colors?: string[]): [string, string, string] {
  return defaultEffectColors.map((fallback, index) => {
    const color = colors?.[index];
    const token = ["primary", "secondary", "tertiary"][index];
    return typeof color === "string" && color.trim()
      ? color.trim()
      : `var(--af-color-${token}, ${fallback})`;
  }) as [string, string, string];
}

export function paletteStyle(colors?: string[]): EffectStyle {
  const [a, b, c] = effectColors(colors);
  return { "--afx-color-a": a, "--afx-color-b": b, "--afx-color-c": c };
}

export type GradientKind = "linear" | "radial" | "mesh";
export type ShaderKind = "aurora" | "waves" | "iridescent" | "none";

export function gradientField(
  kind: GradientKind,
  colors?: string[],
  angle = 135,
) {
  const [a, b, c] = effectColors(colors);
  const degrees = boundedNumber(angle, -3600, 3600, 135);

  if (kind === "linear") {
    return `linear-gradient(${degrees}deg, ${a} 0%, ${b} 52%, ${c} 100%)`;
  }
  if (kind === "radial") {
    return `radial-gradient(ellipse at 72% 28%, ${c} 0%, ${b} 36%, ${a} 72%, #090a16 100%)`;
  }
  return [
    `radial-gradient(ellipse at 82% 18%, ${c} 0%, transparent 46%)`,
    `radial-gradient(ellipse at 68% 78%, ${b} 0%, transparent 55%)`,
    `radial-gradient(ellipse at 15% 24%, ${a} 0%, transparent 62%)`,
    "linear-gradient(135deg, #161027, #090e1d)",
  ].join(", ");
}

/*
 * Colocated, importable mechanics. Every selector is effects-owned; no
 * AppearanceProvider, global effects stylesheet or generated token is needed.
 */
@property --afx-orbit {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@keyframes afx-border-orbit {
  to {
    --afx-orbit: 360deg;
  }
}

@layer components {
  .afx-background {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    background-color: #090a16;
    color: #f8fafc;
  }

  .afx-background-field,
  .afx-shader-canvas,
  .afx-background-scrim {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    user-select: none;
  }

  .afx-background-field {
    opacity: var(--afx-intensity, 0.55);
  }

  .afx-shader-canvas {
    display: block;
    opacity: 0;
    transition: opacity 400ms ease;
  }

  .afx-shader-canvas[data-ready="true"] {
    opacity: 1;
  }

  .afx-shader-canvas[data-ready="false"] {
    transition: none;
  }

  .afx-background-scrim {
    background:
      linear-gradient(90deg, rgb(9 10 22 / 62%), transparent 78%),
      linear-gradient(180deg, rgb(9 10 22 / 8%), rgb(9 10 22 / 48%));
  }

  .afx-background-content {
    position: relative;
    z-index: 1;
    height: 100%;
  }

  .afx-surface {
    position: relative;
    isolation: isolate;
    border-radius: var(--af-radius, 1.25rem);
    border: 1px solid var(--border, rgb(139 92 246 / 20%));
    background-color: var(--surface, #11111f);
    color: var(--foreground, #f8fafc);
    box-shadow: 0 16px 48px -24px rgb(10 8 30 / 42%);
  }

  .afx-spotlight::before,
  .afx-tilt::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
    background: radial-gradient(
      circle var(--afx-spotlight-radius, 320px) at var(--afx-pointer-x, 50%)
        var(--afx-pointer-y, 35%),
      color-mix(
          in srgb,
          var(--afx-spotlight-color, #8b5cf6)
            calc(var(--afx-spotlight-intensity, 0.2) * 100%),
          transparent
        )
        0%,
      transparent 75%
    );
    opacity: 0.65;
    transition: opacity 180ms ease;
  }

  .afx-spotlight[data-afx-pointer="active"]::before,
  .afx-tilt[data-afx-pointer="active"]::before {
    opacity: 1;
  }

  .afx-glow-border::before,
  .afx-glow-border::after {
    content: "";
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: var(--afx-border-width, 1px);
    pointer-events: none;
    background: conic-gradient(
      from var(--afx-orbit),
      var(--afx-color-a, #8b5cf6),
      var(--afx-color-b, #22d3ee) 28%,
      var(--afx-color-c, #34d399) 48%,
      transparent 63%,
      var(--afx-color-a, #8b5cf6) 84%,
      var(--afx-color-b, #22d3ee)
    );
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    animation: afx-border-orbit var(--afx-border-duration, 12s)
      steps(var(--afx-border-steps, 360), end) infinite;
    animation-play-state: paused;
  }

  .afx-glow-border::before {
    opacity: 0.9;
  }

  .afx-glow-border::after {
    inset: -3px;
    opacity: 0.32;
    filter: blur(5px);
  }

  .afx-glow-border[data-afx-motion="running"]::before,
  .afx-glow-border[data-afx-motion="running"]::after {
    animation-play-state: running;
  }

  .afx-tilt {
    transform: perspective(var(--afx-perspective, 900px))
      rotateX(var(--afx-rotate-x, 0deg)) rotateY(var(--afx-rotate-y, 0deg));
    transform-origin: center;
    transition: transform 180ms cubic-bezier(0.2, 0.7, 0.2, 1);
  }

  .afx-magnetic-button {
    position: relative;
    isolation: isolate;
    border: 1px solid rgb(255 255 255 / 18%);
    background: linear-gradient(
      120deg,
      color-mix(in srgb, var(--af-color-primary, #8b5cf6) 40%, #211938),
      #7044d8 58%,
      #3f59aa
    );
    color: #fff;
    box-shadow:
      inset 0 1px 0 rgb(255 255 255 / 16%),
      0 6px 24px -8px rgb(139 92 246 / 56%);
    transform: translate(
      var(--afx-magnetic-x, 0px),
      var(--afx-magnetic-y, 0px)
    );
    transition:
      transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1),
      box-shadow 180ms ease;
    cursor: pointer;
  }

  .afx-magnetic-button:disabled,
  .afx-magnetic-button[aria-disabled="true"],
  .afx-magnetic-button[data-disabled] {
    opacity: 0.5;
    cursor: default;
    transform: none;
  }
}

/* Focus decoration is static and survives every motion preference. */
.afx-surface:focus-visible,
.afx-surface:has(:focus-visible),
.afx-magnetic-button:focus-visible {
  outline: 2px solid var(--ring, #22d3ee);
  outline-offset: 4px;
}

.afx-surface:focus-visible::before,
.afx-surface:has(:focus-visible)::before {
  opacity: 1;
}

.afx-tilt:focus-within,
.afx-magnetic-button:focus-within {
  transform: none;
}

@media (hover: none), (pointer: coarse) {
  .afx-tilt,
  .afx-magnetic-button {
    transform: none;
    transition: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .afx-shader-canvas {
    opacity: 0 !important;
    transition: none;
  }

  .afx-tilt,
  .afx-magnetic-button {
    transform: none;
  }

  .afx-tilt,
  .afx-magnetic-button,
  .afx-spotlight::before,
  .afx-tilt::before {
    transition: none;
  }

  .afx-glow-border::before,
  .afx-glow-border::after {
    animation: none;
  }
}

[data-shader-state="off"] .afx-shader-canvas,
.afx-shader-canvas[data-shader-state="off"] {
  opacity: 0 !important;
  transition: none;
}

.afx-tilt[data-afx-motion="paused"],
.afx-magnetic-button[data-afx-motion="paused"] {
  transform: none;
  transition: none;
}

.afx-spotlight[data-afx-motion="paused"]::before,
.afx-tilt[data-afx-motion="paused"]::before {
  transition: none;
}

.afx-glow-border[data-afx-motion="paused"]::before,
.afx-glow-border[data-afx-motion="paused"]::after {
  animation-play-state: paused;
}

@media (forced-colors: active) {
  .afx-background-field,
  .afx-shader-canvas,
  .afx-background-scrim,
  .afx-spotlight::before,
  .afx-tilt::before,
  .afx-glow-border::before,
  .afx-glow-border::after {
    display: none;
  }

  .afx-background,
  .afx-surface,
  .afx-magnetic-button {
    background: Canvas;
    color: CanvasText;
    border: 1px solid ButtonText;
    box-shadow: none;
  }

  .afx-surface:focus-visible,
  .afx-surface:has(:focus-visible),
  .afx-magnetic-button:focus-visible {
    outline-color: Highlight;
  }
}

