    "--afx-border-steps": Math.floor(orbitDuration * effectFrameRate),
    ...style,
  };
  return (
    <EffectSurface
      {...props}
      ref={mergedRef}
      data-slot="glow-border"
      data-afx-motion="paused"
      className={cn("afx-surface afx-glow-border min-w-0 p-6", className)}
      style={mechanics}
    >
