import type {
  IntegrationAction,
  IntegrationJob,
  IntegrationResult,
  IntegrationValues,
} from "@/lib/integrations/contracts";

type WorkflowHistory = {
  action: IntegrationAction;
  values: IntegrationValues;
  result: IntegrationResult;
};

/**
 * A retry is a new reviewed request using this session's declared inputs.
 * A run ID never substitutes for an unknown workflow/scenario reference.
 */
export function operationalWorkflowRetry(
  action: IntegrationAction | null,
  job: IntegrationJob,
  history: readonly WorkflowHistory[],
) {
  if (
    !action ||
    action.kind !== "trigger-workflow" ||
    !["failed", "cancelled"].includes(job.status)
  )
    return null;
  const original = history.find(
    (entry) =>
      entry.action.kind === "trigger-workflow" &&
      entry.action.id === action.id &&
      entry.result.kind === "job" &&
      entry.result.job.id === job.id,
  );
  if (!original) return null;
  const values: IntegrationValues = {};
  for (const field of action.fields) {
    if (
      /api.?key|token|secret|password|authorization|credential|cookie|private.?key/i.test(
        field.id,
      )
    )
      continue;
    const value = original.values[field.id];
    if (value === undefined) continue;
    values[field.id] = Array.isArray(value) ? [...value] : value;
  }
  return { action, values, sourceRunId: job.id, review: true as const };
}

function reportedText(value: unknown, max: number) {
  return typeof value === "string" &&
    value.trim().length > 0 &&
    value.length <= max &&
    !/[\u0000-\u001f\u007f]/.test(value)
    ? value.trim()
    : null;
}

/** Missing metadata is unknown, not the signed-in user or connection account. */
export function reportedWorkflowMetadata(job: {
  id: string;
  owner?: unknown;
  accounts?: unknown;
  templateUrl?: unknown;
  templateName?: unknown;
}) {
  const reference = (value: unknown) => {
    if (!value || typeof value !== "object" || Array.isArray(value))
      return null;
    const object = value as Record<string, unknown>;
    const id = reportedText(object.id, 200);
    const name = reportedText(object.name, 300);
    return id ? { id, name: name ?? id } : null;
  };
  const reportedAccounts = Array.isArray(job.accounts)
    ? job.accounts.map((value: unknown) => {
        const account = reference(value);
        const status =
          value && typeof value === "object"
            ? (value as Record<string, unknown>).status
            : undefined;
        return account &&
          typeof status === "string" &&
          ["connected", "expired", "revoked", "unknown"].includes(status)
          ? {
              ...account,
              status: status as "connected" | "expired" | "revoked" | "unknown",
            }
          : null;
      })
    : null;
  const accounts =
    reportedAccounts &&
    reportedAccounts.length <= 100 &&
    reportedAccounts.every((value) => value !== null)
      ? reportedAccounts.filter((value) => value !== null)
      : null;
  return {
    owner: reference(job.owner),
    accounts,
    templateUrl: reportedText(job.templateUrl, 8192),
    templateName: reportedText(job.templateName, 300),
  };
}

export function operationalWorkflowAccountStatus(
  status: "connected" | "expired" | "revoked" | "unknown",
): readonly [string, string] {
  const labels = {
    connected: ["Connected", "Conectada"],
    expired: ["Expired", "Caducada"],
    revoked: ["Revoked", "Revocada"],
    unknown: ["Unknown", "Desconocida"],
  } as const;
  return labels[status];
}

/** Public discovery links only; these neither create nor activate automations. */
export function operationalWorkflowTemplateCatalog(providerId: string) {
  if (providerId === "make")
    return {
      provider: "Make",
      url: "https://www.make.com/templates",
    };
  if (providerId === "zapier")
    return {
      provider: "Zapier",
      url: "https://zapier.com/templates",
    };
  return null;
}

"use client";

import { ArrowRight, ArrowUpRight, GitBranch, ListChecks } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { useLanguage } from "@/hooks/use-language";
import type { IntegrationToolRun } from "@/lib/integrations/contracts";
import { isIntegrationTraceUrl } from "@/lib/integrations/validation";
import { publicPath } from "@/lib/public-path";

/** Syntax checking is separate from the backend's authorization of the trace. */
export function productAgentTraceHref(value?: string, demo = false) {
  return !demo && typeof value === "string" && value.length <= 2048 && isIntegrationTraceUrl(value)
    ? publicPath(value)
    : undefined;
}

/** Reads only published run fields; inputs, reasoning and raw payloads are excluded. */
export function ProductAgentRunSummary({
  run,
  demo = false,
}: {
  run: IntegrationToolRun;
  demo?: boolean;
}) {
  const { locale, l } = useLanguage();
  const stateLabels = {
    requested: l("Requested", "Solicitado"),
    accepted: l("Accepted", "Aceptado"),
    queued: l("Queued", "En cola"),
    running: l("Running", "En curso"),
    completed: l("Completed", "Completado"),
    failed: l("Failed", "Fallido"),
    rejected: l("Rejected", "Rechazado"),
    cancelled: l("Cancelled", "Cancelado"),
  };
  const number = (value: number | null) => value === null
    ? l("Unknown", "Desconocido")
    : new Intl.NumberFormat(locale).format(value);
  const href = productAgentTraceHref(run.safeTraceUrl, demo);
  const terminal = ["completed", "failed", "rejected"].includes(run.state);
  const progress = run.progress;
  return (
    <section className="mt-5 min-w-0 space-y-4 border-t border-border/70 pt-4"
      data-product-agent-run={run.id} aria-label={l("Published execution details", "Detalles publicados de la ejecución")}>
      <div className="flex min-w-0 flex-wrap items-center gap-2 text-[11px] text-muted-foreground">
        <Badge variant="neutral">{demo ? l("Local simulation", "Simulación local") : l("Backend reported", "Reportado por el backend")}</Badge>
        <span className="min-w-0 break-all">{l("Run", "Ejecución")}: <span className="font-mono">{run.id}</span></span>
      </div>
      {demo && <p className="text-xs leading-6 text-muted-foreground">
        {l("Local fixtures only; no agent service was called.", "Solo datos locales de ejemplo; no se llamó a un servicio de agentes.")}
      </p>}
      {progress ? (
        <div className="min-w-0 rounded-xl border border-border bg-surface-subtle/50 p-4"
          data-product-agent-progress-state={progress.state}
          data-product-agent-last-reported={terminal && ["queued", "running"].includes(progress.state) || undefined}>
          <div className="flex min-w-0 flex-wrap items-center gap-2.5">
            <ListChecks className="size-4 shrink-0 text-primary" aria-hidden="true" />
            <p className="min-w-0 flex-1 break-words text-xs font-semibold">{progress.label}</p>
            <Badge variant={progress.state === "failed" ? "destructive" : progress.state === "completed" ? "default" : "neutral"}>
              {stateLabels[progress.state]}
            </Badge>
          </div>
          <p className="mt-3 whitespace-pre-wrap break-words text-xs leading-6 text-muted-foreground">{progress.summary}</p>
          <p className="mt-3 text-xs" data-product-agent-counts>
            {progress.completed === null && progress.total === null
              ? l("Counts not reported", "Cifras no reportadas")
              : <>{l("Completed units", "Unidades completadas")}: <span className="font-mono">{number(progress.completed)} / {number(progress.total)}</span></>}
          </p>
          {terminal && ["queued", "running"].includes(progress.state) && <p className="mt-2 text-[11px] leading-6 text-muted-foreground">
            {l("Last reported progress; the run has ended.", "Último progreso reportado; la ejecución ha terminado.")}
          </p>}
        </div>
      ) : <p className="text-xs text-muted-foreground">{l("Progress not reported", "Progreso no reportado")}</p>}
      {run.handoffs?.length ? (
        <div className="min-w-0">
          <h5 className="mb-3 text-xs font-semibold">{l("Agent handoffs", "Transferencias entre agentes")}</h5>
          <ol className="grid min-w-0 gap-3">
            {run.handoffs.map((handoff) => {
              const lastReported = terminal && ["requested", "accepted"].includes(handoff.state);
              return (
                <li key={handoff.id} className="min-w-0 rounded-xl border border-primary/20 bg-accent/20 p-4"
                  data-product-agent-handoff={handoff.id} data-product-agent-handoff-state={handoff.state}
                  data-product-agent-last-reported={lastReported || undefined}>
                  <div className="flex min-w-0 flex-wrap items-center gap-2.5">
                    <GitBranch className="size-4 shrink-0 text-primary" aria-hidden="true" />
                    <p className="min-w-0 flex-1 break-words text-xs font-medium">
                      {handoff.from}<ArrowRight className="mx-2 inline size-3" aria-hidden="true" />{handoff.to}
                    </p>
                    <Badge variant={handoff.state === "failed" ? "destructive" : handoff.state === "completed" ? "default" : "neutral"}>
                      {stateLabels[handoff.state]}
                    </Badge>
                  </div>
                  <p className="mt-3 whitespace-pre-wrap break-words text-xs leading-6 text-muted-foreground">{handoff.summary}</p>
                  {lastReported && <p className="mt-2 text-[11px] leading-6 text-muted-foreground">
                    {l("Last reported handoff; the run has ended.", "Última transferencia reportada; la ejecución ha terminado.")}
                  </p>}
                </li>
              );
            })}
          </ol>
        </div>
      ) : <p className="text-xs text-muted-foreground">
        {run.handoffs
          ? l("No handoffs in this run", "Esta ejecución no tiene transferencias")
          : l("Handoffs not reported", "Transferencias no reportadas")}
      </p>}
      {href ? (
        <a href={href} target="_blank" rel="noopener noreferrer" data-product-agent-trace
          className="inline-flex min-h-11 max-w-full items-center gap-1.5 rounded-lg px-2 text-xs font-semibold text-primary underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
          <span>{l("Open approved trace", "Abrir traza aprobada")}</span>
          <ArrowUpRight className="size-3.5 shrink-0" aria-hidden="true" />
          <span className="sr-only">{l("(new tab)", "(pestaña nueva)")}</span>
        </a>
      ) : <p className="text-xs text-muted-foreground" data-product-agent-trace-unavailable>
        {l("Trace unavailable", "Traza no disponible")}
      </p>}
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  Check,
  ListRestart,
  Play,
  Plus,
  RefreshCw,
  ShieldCheck,
  X,
} from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { ProductAgentRunSummary } from "./product-agent-run";
import type {
  IntegrationAction,
  IntegrationJob,
  IntegrationRecord,
  IntegrationToolRun,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import {
  findProductAction,
  invalidProductField,
  parseProductArguments,
  productActionValues,
  productReadDefaults,
  productToolFields,
} from "./product-model";
import {
  ProductActionUnavailable,
  ProductDocumentPreview,
  ProductEmpty,
  ProductFields,
  ProductJobResult,
  ProductLabeledTextarea,
  ProductOperationFeedback,
  ProductPanel,
  ProductRecordList,
  ProductResourcePicker,
  ProductResult,
  ProductReview,
  ProductStatus,
  ProductValidation,
  useProductResources,
} from "./product-ui";

export function ProductAgentsWorkbench(props: IntegrationWorkbenchProps) {
  const { l } = useLanguage();
  const read = useIntegrationOperation(props);
  const execute = useIntegrationOperation(props);
  const approval = useIntegrationOperation(props);
  const resources = useProductResources(props);
  const queryAction = findProductAction(props.definition, "query");
  const agentAction = findProductAction(props.definition, "run-agent");
  const toolAction = findProductAction(props.definition, "execute-tool");
  const approveAction = findProductAction(props.definition, "approve-tool");
  const checkpointAction = findProductAction(props.definition, "checkpoint");
  const [resourceId, setResourceId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [tools, setTools] = useState<IntegrationRecord[]>([]);
  const [toolId, setToolId] = useState("");
  const [manualToolName, setManualToolName] = useState("");
  const [toolValues, setToolValues] = useState<IntegrationValues>({});
  const [parameters, setParameters] = useState<
    { name: string; value: string }[]
  >([]);
  const [structured, setStructured] = useState(false);
  const [inputText, setInputText] = useState("{}");
  const [mode, setMode] = useState(agentAction ? "agent" : "tool");
  const [goal, setGoal] = useState("");
  const [extra, setExtra] = useState<IntegrationValues>(() =>
    productReadDefaults(queryAction, props),
  );
  const [run, setRun] = useState<IntegrationToolRun | null>(null);
  const [submittedApproval, setSubmittedApproval] = useState("");
  const [history, setHistory] = useState<IntegrationToolRun[]>([]);
  const [job, setJob] = useState<IntegrationJob | null>(null);
  const [checkpoints, setCheckpoints] = useState<IntegrationRecord[]>([]);
  const [checkpointId, setCheckpointId] = useState("");
  const [review, setReview] = useState<{
    action: IntegrationAction;
    values: IntegrationValues;
    lane: "execute" | "approval";
  } | null>(null);
  const selectedTool = tools.find((tool) => tool.id === toolId);
  const toolName = selectedTool?.name ?? manualToolName.trim();
  const fields = useMemo(() => productToolFields(selectedTool), [selectedTool]);
  const action = mode === "agent" ? agentAction : toolAction;
  const parameterNames = parameters.map((parameter) => parameter.name.trim());
  const validParameters =
    parameterNames.every(
      (name) =>
        name && !["__proto__", "constructor", "prototype"].includes(name),
    ) && new Set(parameterNames).size === parameterNames.length;
  const input: IntegrationValues = fields.length
    ? toolValues
    : Object.fromEntries(
        parameters.map((parameter) => [parameter.name.trim(), parameter.value]),
      );
  const structuredInput = parseProductArguments(inputText);
  const serializedInput = structured ? inputText : JSON.stringify(input);
  const inputValid = !structured
    ? validParameters && !invalidProductField({ fields }, toolValues)
    : structuredInput.ok;
  const prepared = productActionValues(
    action,
    {
      ...extra,
      toolId,
      tool: toolName,
      toolName,
      goal,
      prompt: goal,
      task: goal,
      input: serializedInput,
      arguments: serializedInput,
      checkpointId,
    },
    resourceId,
  );

  async function discover(view = "tools") {
    if (!queryAction) return;
    const values = productActionValues(
      queryAction,
      { ...extra, view, runId: run?.id ?? job?.id ?? extra.runId ?? "" },
      resourceId,
    );
    if (invalidProductField(queryAction, values)) return;
    const result = await read.run(queryAction, values);
    if (result?.kind === "records") {
      if (view === "checkpoints") setCheckpoints(result.records);
      else if (view === "tools") setTools(result.records);
    }
    if (result?.kind === "tool") acceptRun(result.run);
    if (result?.kind === "job") setJob(result.job);
  }
  function acceptRun(value: IntegrationToolRun) {
    setReview(null);
    setRun(value);
    setHistory((items) =>
      [...items.filter((item) => item.id !== value.id), value].slice(-30),
    );
  }
  function stage(
    target: IntegrationAction | undefined,
    values: IntegrationValues,
    lane: "execute" | "approval" = "execute",
  ) {
    if (!target) return;
    const input = productActionValues(target, values, resourceId);
    if (!invalidProductField(target, input))
      setReview({ action: target, values: input, lane });
  }
  async function submit() {
    if (!review) return;
    const result = await (review.lane === "approval" ? approval : execute).run(
      review.action,
      review.values,
    );
    if (!result) return;
    if (result.kind === "tool") acceptRun(result.run);
    if (result.kind === "job") setJob(result.job);
    if (review.action.kind === "approve-tool")
      setSubmittedApproval(String(review.values.approvalId ?? ""));
    if (review.action.kind === "checkpoint" && result.kind === "receipt")
      setCheckpointId(result.id);
    setReview(null);
  }
  const busy = execute.pending || approval.pending;
  const canApprove =
    run?.state === "approval-required" &&
    Boolean(run.approvalId) &&
    Boolean(approveAction) &&
    submittedApproval !== run.approvalId;

  return (
    <div className="space-y-5">
      <ProductPanel
        title={l(
          "Agent and tool discovery",
          "Descubrimiento de agentes y herramientas",
        )}
        description={l(
          "Discover tools through the selected connection and review each requested action.",
          "Descubre herramientas mediante la conexión seleccionada y revisa cada acción solicitada.",
        )}
      >
        <ProductResourcePicker
          {...resources}
          value={resourceId}
          onChange={(value) => {
            [read, execute, approval].forEach((operation) => operation.reset());
            setResourceId(value);
            setTools([]);
            setToolId("");
            setManualToolName("");
            setRun(null);
            setSubmittedApproval("");
            setJob(null);
            setHistory([]);
            setReview(null);
          }}
          disabled={busy}
        />
        <div className="mt-4">
          <ProductFields
            action={queryAction}
            values={extra}
            onChange={(value) => {
              setExtra(value);
              setReview(null);
            }}
            exclude={["resourceId", "view"]}
          />
        </div>
        <div className="my-4 flex flex-wrap gap-2">
          <Button
            variant="outline"
            loading={read.pending}
            disabled={!queryAction || busy}
            onClick={() => {
              void discover();
            }}
          >
            <RefreshCw />
            {queryAction
              ? l(queryAction.label.en, queryAction.label.es)
              : l(
                  "Discover available tools",
                  "Descubrir herramientas disponibles",
                )}
          </Button>
          <Button
            variant="outline"
            disabled={!queryAction || busy || read.pending || (!run && !job)}
            onClick={() => {
              void discover("run");
            }}
          >
            {l("Refresh execution", "Actualizar ejecución")}
          </Button>
        </div>
        <ProductRecordList
          records={tools}
          selected={toolId}
          onSelect={(tool) => {
            if (!toolAction) {
              setExtra((values) => ({
                ...values,
                threadId: tool.id,
                runId: tool.id,
              }));
              setReview(null);
              return;
            }
            setToolId(tool.id);
            setMode("tool");
            const schemaFields = productToolFields(tool);
            setToolValues(
              Object.fromEntries(
                schemaFields.map((field) => [
                  field.id,
                  field.type === "toggle"
                    ? false
                    : (field.options?.[0]?.value ?? ""),
                ]),
              ),
            );
            setParameters([]);
            setInputText("{}");
            setReview(null);
          }}
        />
        <ProductOperationFeedback operation={read} />
        <ProductActionUnavailable action={queryAction} />
      </ProductPanel>
      <ProductPanel title={l("Prepare an execution", "Preparar una ejecución")}>
        <div className="space-y-4">
          <Select
            label={l("Execution type", "Tipo de ejecución")}
            value={mode}
            onValueChange={(value) => {
              setMode(value);
              setReview(null);
            }}
            options={[
              {
                value: "agent",
                label: l("Agent task", "Tarea de agente"),
                disabled: !agentAction,
              },
              {
                value: "tool",
                label: l("Tool call", "Llamada a herramienta"),
                disabled: !toolAction,
              },
            ]}
          />
          {mode === "agent" ? (
            <ProductLabeledTextarea
              label={l(
                "Task and expected outcome",
                "Tarea y resultado esperado",
              )}
              value={goal}
              onChange={(event) => {
                setGoal(event.target.value);
                setReview(null);
              }}
              disabled={busy}
            />
          ) : (
            <>
              <Select
                label={l("Discovered tool", "Herramienta descubierta")}
                value={toolId}
                options={tools.map((tool) => ({
                  value: tool.id,
                  label: tool.name,
                }))}
                onValueChange={(value) => {
                  setToolId(value);
                  setManualToolName("");
                  setToolValues({});
                  setReview(null);
                }}
                disabled={busy}
              />
              <label className="block space-y-2 text-xs font-medium">
                {l(
                  "Or enter a tool name exposed by your backend",
                  "O introduce una herramienta expuesta por tu backend",
                )}
                <Input
                  value={manualToolName}
                  disabled={busy}
                  onChange={(event) => {
                    setManualToolName(event.target.value);
                    setToolId("");
                    setToolValues({});
                    setReview(null);
                  }}
                />
                <span className="block font-normal leading-6 text-muted-foreground">
                  {l(
                    "Your backend must resolve the name against its authorized tool catalog.",
                    "Tu backend debe resolver el nombre en su catálogo de herramientas autorizadas.",
                  )}
                </span>
              </label>
              {selectedTool && (
                <p className="text-xs leading-6 text-muted-foreground">
                  {selectedTool.description}
                </p>
              )}
              <label className="flex min-h-11 items-center gap-2 text-xs">
                <Checkbox
                  checked={structured}
                  onCheckedChange={(value) => {
                    setStructured(value);
                    setReview(null);
                  }}
                  disabled={busy}
                />
                {l("Use a JSON input object", "Usar un objeto JSON de entrada")}
              </label>
              {structured ? (
                <ProductLabeledTextarea
                  label={l("Tool arguments", "Argumentos de la herramienta")}
                  value={inputText}
                  className="font-mono text-xs"
                  spellCheck={false}
                  aria-invalid={!inputValid}
                  onChange={(event) => {
                    setInputText(event.target.value);
                    setReview(null);
                  }}
                  disabled={busy}
                />
              ) : fields.length ? (
                <ProductFields
                  fields={fields}
                  values={toolValues}
                  onChange={(value) => {
                    setToolValues(value);
                    setReview(null);
                  }}
                  disabled={busy}
                />
              ) : (
                <div className="space-y-3">
                  {parameters.map((parameter, index) => (
                    <div
                      key={index}
                      className="grid grid-cols-[1fr_1fr_auto] gap-2"
                    >
                      <Input
                        aria-label={`${l("Parameter name", "Nombre del parámetro")} ${index + 1}`}
                        value={parameter.name}
                        disabled={busy}
                        onChange={(event) => {
                          setParameters((items) =>
                            items.map((item, i) =>
                              i === index
                                ? { ...item, name: event.target.value }
                                : item,
                            ),
                          );
                          setReview(null);
                        }}
                      />
                      <Input
                        aria-label={`${l("Parameter value", "Valor del parámetro")} ${index + 1}`}
                        value={parameter.value}
                        disabled={busy}
                        onChange={(event) => {
                          setParameters((items) =>
                            items.map((item, i) =>
                              i === index
                                ? { ...item, value: event.target.value }
                                : item,
                            ),
                          );
                          setReview(null);
                        }}
                      />
                      <Button
                        variant="ghost"
                        size="icon"
                        disabled={busy}
                        aria-label={l("Remove parameter", "Quitar parámetro")}
                        onClick={() => {
                          setParameters((items) =>
                            items.filter((_, i) => i !== index),
                          );
                          setReview(null);
                        }}
                      >
                        <X />
                      </Button>
                    </div>
                  ))}
                  <Button
                    variant="outline"
                    size="sm"
                    disabled={busy}
                    onClick={() =>
                      setParameters((items) => [
                        ...items,
                        { name: "", value: "" },
                      ])
                    }
                  >
                    <Plus />
                    {l("Add parameter", "Añadir parámetro")}
                  </Button>
                </div>
              )}
              {!inputValid && (
                <p role="alert" className="text-xs text-destructive-foreground">
                  {l(
                    "Complete the tool fields, use unique parameter names, or provide a valid JSON arguments object.",
                    "Completa los campos de la herramienta, usa nombres únicos o introduce un objeto JSON válido de argumentos.",
                  )}
                </p>
              )}
            </>
          )}
          <ProductFields
            action={action}
            values={extra}
            onChange={(value) => {
              setExtra(value);
              setReview(null);
            }}
            disabled={busy}
            exclude={[
              "resourceId",
              "toolId",
              "tool",
              "toolName",
              "goal",
              "prompt",
              "task",
              "input",
              "arguments",
              "checkpointId",
            ]}
          />
          <label className="block space-y-2 text-xs font-medium">
            {l(
              "Resume checkpoint ID (optional)",
              "ID del punto de reanudación (opcional)",
            )}
            <Input
              value={checkpointId}
              onChange={(event) => {
                setCheckpointId(event.target.value);
                setReview(null);
              }}
              disabled={busy}
            />
          </label>
          <ProductValidation action={action} values={prepared} />
          <Button
            appearance="gradient"
            disabled={
              !action ||
              busy ||
              Boolean(invalidProductField(action, prepared)) ||
              (mode === "agent" ? !goal.trim() : !toolName || !inputValid)
            }
            onClick={() => stage(action, prepared)}
          >
            <Play />
            {l("Review execution", "Revisar ejecución")}
          </Button>
          <ProductActionUnavailable action={action} />
          <ProductOperationFeedback operation={execute} />
        </div>
      </ProductPanel>
      {run && (
        <ProductPanel
          title={l(
            "Tool action and approval",
            "Acción y aprobación de herramienta",
          )}
        >
          <div className="mb-4 flex flex-wrap items-center gap-3">
            <ShieldCheck className="size-4 text-primary" />
            <h4 className="text-sm font-medium">{run.name}</h4>
            <ProductStatus value={run.state} />
          </div>
          <ProductDocumentPreview
            content={JSON.stringify(run.input)}
            format="json"
          />
          {run.state === "approval-required" && (
            <div className="mt-4 space-y-3">
              <p className="text-xs leading-6">
                {l(
                  "Review the input returned by the backend before approving or rejecting this pending action.",
                  "Revisa la entrada devuelta por el backend antes de aprobar o rechazar esta acción pendiente.",
                )}
              </p>
              <ProductFields
                action={approveAction}
                values={extra}
                onChange={(value) => {
                  setExtra(value);
                  setReview(null);
                }}
                exclude={[
                  "resourceId",
                  "approvalId",
                  "runId",
                  "decision",
                  "approved",
                ]}
                disabled={busy}
              />
              <div className="flex flex-wrap gap-2">
                <Button
                  appearance="gradient"
                  disabled={!canApprove || busy}
                  onClick={() =>
                    stage(
                      approveAction,
                      {
                        ...extra,
                        approvalId: run.approvalId!,
                        runId: run.id,
                        decision: "approve",
                        approved: true,
                      },
                      "approval",
                    )
                  }
                >
                  <Check />
                  {l("Review approval", "Revisar aprobación")}
                </Button>
                <Button
                  variant="outline"
                  disabled={!canApprove || busy}
                  onClick={() =>
                    stage(
                      approveAction,
                      {
                        ...extra,
                        approvalId: run.approvalId!,
                        runId: run.id,
                        decision: "reject",
                        approved: false,
                      },
                      "approval",
                    )
                  }
                >
                  <X />
                  {l("Review rejection", "Revisar rechazo")}
                </Button>
              </div>
              {!run.approvalId && (
                <p role="alert" className="text-xs text-destructive-foreground">
                  {l(
                    "The backend did not provide an approval ID. Reload this execution before making a decision.",
                    "El backend no proporcionó un ID de aprobación. Recarga la ejecución antes de decidir.",
                  )}
                </p>
              )}
              <ProductActionUnavailable action={approveAction} />
            </div>
          )}
          {run.output && (
            <div className="mt-5">
              <ProductDocumentPreview content={run.output} format="markdown" />
            </div>
          )}
          <ProductAgentRunSummary run={run} demo={props.adapter.mode === "demo"} />
          <div className="mt-4">
            <ProductOperationFeedback operation={approval} />
            {approval.result && approval.result.kind !== "tool" && (
              <>
                <ProductResult result={approval.result} />
                <p className="mt-2 text-xs text-muted-foreground">
                  {l(
                    "Decision submitted. Refresh the execution to inspect its backend state.",
                    "Decisión enviada. Actualiza la ejecución para consultar su estado en el backend.",
                  )}
                </p>
              </>
            )}
          </div>
        </ProductPanel>
      )}
      {job && (
        <ProductPanel
          title={l(
            "Execution progress and logs",
            "Progreso y registro de ejecución",
          )}
        >
          <ProductJobResult job={job} />
        </ProductPanel>
      )}
      <ProductPanel
        title={l(
          "Checkpoints and execution history",
          "Puntos de control e historial",
        )}
      >
        <div className="mb-4 space-y-3">
          <ProductFields
            action={checkpointAction}
            values={extra}
            onChange={(value) => {
              setExtra(value);
              setReview(null);
            }}
            exclude={["resourceId", "runId"]}
            disabled={busy}
          />
          <div className="flex flex-wrap gap-2">
            <Button
              variant="outline"
              disabled={!checkpointAction || busy || (!run && !job)}
              onClick={() =>
                stage(checkpointAction, {
                  ...extra,
                  runId: run?.id ?? job?.id ?? "",
                })
              }
            >
              <ListRestart />
              {l("Review checkpoint", "Revisar punto de control")}
            </Button>
            <Button
              variant="outline"
              disabled={!queryAction || read.pending}
              onClick={() => {
                void discover("checkpoints");
              }}
            >
              {l("Load checkpoints", "Cargar puntos de control")}
            </Button>
          </div>
        </div>
        {checkpoints.length > 0 && (
          <ProductRecordList
            records={checkpoints}
            selected={checkpointId}
            onSelect={(record) => {
              setCheckpointId(record.id);
              setReview(null);
            }}
          />
        )}
        {history.length ? (
          <ol className="space-y-2">
            {history.map((item) => (
              <li
                key={item.id}
                className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border p-3"
              >
                <div>
                  <p className="text-xs font-medium">{item.name}</p>
                  <p className="mt-1 text-[10px] text-muted-foreground">
                    {item.id}
                  </p>
                </div>
                <ProductStatus value={item.state} />
                <Button
                  size="sm"
                  variant="ghost"
                  disabled={busy}
                  onClick={() => {
                    setRun(item);
                    setReview(null);
                  }}
                >
                  {l("Inspect", "Revisar")}
                </Button>
              </li>
            ))}
          </ol>
        ) : (
          <ProductEmpty>
            {l(
              "Completed requests and backend checkpoints will appear here.",
              "Las solicitudes realizadas y los puntos de control del backend aparecerán aquí.",
            )}
          </ProductEmpty>
        )}
        {execute.result && !["tool", "job"].includes(execute.result.kind) && (
          <div className="mt-4">
            <ProductResult result={execute.result} />
          </div>
        )}
      </ProductPanel>
      {review && (
        <ProductReview
          action={review.action}
          values={review.values}
          pending={busy}
          grantedPermissions={props.connection.grantedPermissions}
          disabled={
            review.lane === "approval" &&
            (run?.approvalId !== review.values.approvalId ||
              submittedApproval === review.values.approvalId)
          }
          onConfirm={() => {
            void submit();
          }}
          onReject={() => setReview(null)}
        >
          {review.values.input && (
            <div className="mb-4">
              <ProductDocumentPreview
                content={String(review.values.input)}
                format="json"
              />
            </div>
          )}
          {review.action.kind === "approve-tool" && run && (
            <div className="mb-4">
              <p className="mb-2 text-xs font-semibold">{run.name}</p>
              <ProductDocumentPreview
                content={JSON.stringify(run.input)}
                format="json"
              />
            </div>
          )}
        </ProductReview>
      )}
    </div>
  );
}

import type {
  IntegrationAction,
  IntegrationRecord,
  IntegrationUpdate,
  IntegrationValues,
} from "../../lib/integrations/contracts";

export type ProductCollaborationScope = {
  resourceId: string;
  workspaceId: string;
  connectionId: string;
  integrationId: string;
};

export type ProductReplyTarget = {
  resourceId: string;
  threadId: string;
  parentId: string;
};

export type ProductReportedMessage = {
  record: IntegrationRecord;
  threadId?: string;
  parentId?: string;
  parent?: IntegrationRecord;
  relation: "flat" | "root" | "reply" | "parent-unavailable" | "invalid";
  replyTarget?: ProductReplyTarget;
};

export type ProductReportedConversation = {
  resourceId: string;
  messages: ProductReportedMessage[];
  flat: ProductReportedMessage[];
  threads: { id: string; messages: ProductReportedMessage[] }[];
};

const messageTypes = new Set(["message", "chat", "comment"]);

function reportedText(value: unknown, maximum: number) {
  return typeof value === "string" &&
    value.length <= maximum &&
    value.trim().length > 0 &&
    !/[\u0000-\u001f\u007f]/.test(value)
    ? value
    : undefined;
}

function reportedId(value: unknown) {
  return reportedText(value, 200);
}

/** Local assets/proxy paths or HTTPS images; no credentials or alternate schemes. */
export function productPresenceAvatarUrl(value: unknown) {
  if (
    typeof value !== "string" ||
    !value ||
    value.length > 8192 ||
    value !== value.trim() ||
    /[\\\u0000-\u001f\u007f]/.test(value)
  )
    return undefined;
  if (value.startsWith("/")) return value.startsWith("//") ? undefined : value;
  try {
    const url = new URL(value);
    return url.protocol === "https:" && !url.username && !url.password
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
}

/** Presence is a server snapshot, including an empty snapshot; never seed people. */
export function productPresenceRecords(
  members: Extract<IntegrationUpdate, { kind: "presence" }>["members"],
): IntegrationRecord[] {
  const seen = new Set<string>();
  return members.slice(0, 1000).flatMap((member) => {
    const id = reportedId(member.id);
    const name = reportedText(member.name, 160);
    if (!id || !name || seen.has(id)) return [];
    seen.add(id);
    const avatarUrl = productPresenceAvatarUrl(member.avatarUrl);
    return [
      {
        id,
        name,
        type: "presence",
        status: member.state,
        description: "",
        updatedAt: "",
        ...(avatarUrl ? { fields: { avatarUrl } } : {}),
      },
    ];
  });
}

/** Join an author to presence by an explicit ID, never by a guessed display name. */
export function productCollaborationAuthor(
  record: IntegrationRecord,
  presence: readonly IntegrationRecord[],
) {
  const id = reportedId(record.fields?.authorId);
  const matching = id ? presence.filter((member) => member.id === id) : [];
  const member = matching.length === 1 ? matching[0] : undefined;
  return {
    id,
    name:
      reportedText(record.fields?.authorName, 160) ??
      reportedText(member?.name, 160),
    avatarUrl: member
      ? productPresenceAvatarUrl(member.fields?.avatarUrl)
      : undefined,
  };
}

/**
 * Query/room-specific subscriptions may omit redundant room fields. A connection
 * stream must report a resource before its records can enter a selected room.
 */
export function productCollaborationRecords(
  records: readonly IntegrationRecord[],
  scope: ProductCollaborationScope,
  requireResource = false,
) {
  return records.filter((record) => {
    const fields = record.fields ?? {};
    const bindings = ["resourceId", "roomId", "channelId"];
    if (
      requireResource &&
      !bindings.some((key) => reportedId(fields[key]) !== undefined)
    )
      return false;
    return (
      bindings.every(
        (key) =>
          fields[key] === undefined ||
          fields[key] === "" ||
          fields[key] === scope.resourceId,
      ) &&
      ["workspaceId", "connectionId", "integrationId"].every(
        (key) =>
          fields[key] === undefined ||
          fields[key] === scope[key as keyof ProductCollaborationScope],
      )
    );
  });
}

/**
 * Bounded, flat projection. Only reported thread IDs create groups; a reply label
 * requires a loaded parent in that same group. Missing history stays visible.
 */
export function productReportedConversation(
  records: readonly IntegrationRecord[],
  scope: ProductCollaborationScope,
): ProductReportedConversation {
  const loaded = productCollaborationRecords(records.slice(-100), scope).filter(
    (record) => messageTypes.has(record.type),
  );
  const counts = new Map<string, number>();
  for (const record of loaded)
    counts.set(record.id, (counts.get(record.id) ?? 0) + 1);
  const messages: ProductReportedMessage[] = loaded.map((record) => {
    const threadId = reportedId(record.fields?.threadId);
    const parentId = reportedId(record.fields?.parentId);
    const invalidParent =
      record.fields?.parentId !== undefined &&
      record.fields.parentId !== "" &&
      !parentId;
    if (!reportedId(record.id) || counts.get(record.id) !== 1 || invalidParent)
      return { record, relation: "invalid" };
    if (!threadId) return { record, relation: "flat" };
    return {
      record,
      threadId,
      parentId,
      relation: parentId ? "parent-unavailable" : "root",
    };
  });
  const byId = new Map(
    messages
      .filter((message) => counts.get(message.record.id) === 1)
      .map((message) => [message.record.id, message]),
  );
  const groups = new Map<string, ProductReportedMessage[]>();
  for (const message of messages) {
    if (!message.threadId) continue;
    if (message.parentId) {
      const parent = byId.get(message.parentId);
      if (parent) {
        if (
          parent === message ||
          parent.threadId !== message.threadId ||
          parent.relation === "invalid"
        )
          message.relation = "invalid";
        else {
          message.parent = parent.record;
          message.relation = "reply";
        }
      }
    }
    // No recursive rendering or inferred roots, including cyclic provider data.
    const visited = new Set<string>([message.record.id]);
    let ancestor = message.parentId;
    while (ancestor) {
      if (visited.has(ancestor)) {
        message.relation = "invalid";
        message.parent = undefined;
        break;
      }
      visited.add(ancestor);
      const parent = byId.get(ancestor);
      if (!parent || parent.threadId !== message.threadId) break;
      ancestor = parent.parentId;
    }
    if (
      message.relation !== "invalid" &&
      reportedId(scope.resourceId) &&
      !["deleted", "removed", "deleting"].includes(message.record.status)
    )
      message.replyTarget = {
        resourceId: scope.resourceId,
        threadId: message.threadId,
        parentId: message.record.id,
      };
    const group = groups.get(message.threadId) ?? [];
    group.push(message);
    groups.set(message.threadId, group);
  }
  return {
    resourceId: scope.resourceId,
    messages,
    flat: messages.filter((message) => !message.threadId),
    threads: [...groups].map(([id, items]) => ({ id, messages: items })),
  };
}

/** Revalidate at review/confirmation; never downgrade a disappeared reply to a post. */
export function productReplyIsCurrent(
  conversation: ProductReportedConversation,
  target: ProductReplyTarget,
) {
  return (
    conversation.resourceId === target.resourceId &&
    conversation.messages.some(
      (message) =>
        message.replyTarget?.threadId === target.threadId &&
        message.replyTarget.parentId === target.parentId &&
        message.replyTarget.resourceId === target.resourceId,
    )
  );
}

export function productSupportsReplies(action?: IntegrationAction) {
  return (
    action?.kind === "publish-message" &&
    ["threadId", "parentId"].every((id) =>
      action.fields.some((field) => field.id === id && field.type === "text"),
    )
  );
}

/**
 * Build only declared inputs. Room and reply IDs come from the selected context;
 * author identity is supplied by the backend, not editable frontend values.
 */
export function productCollaborationPublishValues({
  action,
  extra,
  message,
  conversation,
  reply,
}: {
  action?: IntegrationAction;
  extra: IntegrationValues;
  message: string;
  conversation: ProductReportedConversation;
  reply: ProductReplyTarget | null;
}): IntegrationValues | undefined {
  if (
    !action ||
    action.kind !== "publish-message" ||
    !reportedId(conversation.resourceId) ||
    (reply &&
      (!productSupportsReplies(action) ||
        !productReplyIsCurrent(conversation, reply)))
  )
    return undefined;
  const values: IntegrationValues = {};
  for (const field of action.fields) {
    if (["threadId", "parentId", "authorId", "authorName"].includes(field.id))
      continue;
    if (["resourceId", "roomId", "channelId"].includes(field.id))
      values[field.id] = conversation.resourceId;
    else if (["message", "content"].includes(field.id))
      values[field.id] = message;
    else
      values[field.id] =
        extra[field.id] ??
        (field.type === "toggle"
          ? false
          : field.type === "select"
            ? (field.options?.[0]?.value ?? "")
            : "");
  }
  if (reply) {
    values.threadId = reply.threadId;
    values.parentId = reply.parentId;
  }
  return values;
}

