                  </>
                )}
                <ProductResult result={write.result} />
              </div>
            )}
          </div>
        </ProductPanel>
      </div>
      {findProductAction(props.definition, "save-document") && (
        <ProductDocumentWorkbench {...props} />
      )}
      {findProductAction(props.definition, "execute-tool", "run-agent") && (
        <ProductAgentsWorkbench {...props} />
      )}
      {review && (
        <ProductReview
          action={review.action}
          values={review.values}
          pending={write.pending}
          disabled={
            staleReview ||
            (Boolean(review.target) &&
              (Boolean(comparison) || remoteRead.pending))
          }
          grantedPermissions={props.connection.grantedPermissions}
          onConfirm={() => {
            void submit();
          }}
          onReject={() => setReview(null)}
        >
          {review.target && (
            <div className="mb-4 space-y-2 rounded-xl border border-border bg-surface-subtle/40 p-4 text-xs leading-6">
              <p>
                {l("Reviewed record", "Registro revisado")}:{" "}
                {review.target.name} · {review.target.id}
              </p>
              <p data-reviewed-target-revision={review.target.updatedAt}>
                {l("Reviewed remote revision", "Revisión remota revisada")}:{" "}
                {review.target.updatedAt}
              </p>
              {staleReview && (
                <p role="alert" className="text-destructive-foreground">
                  {l(
                    "The target changed after this review. Read it again and review your preserved draft.",
                    "El registro cambió después de esta revisión. Léelo de nuevo y revisa tu borrador conservado.",
                  )}
                </p>
              )}
            </div>
          )}
          {(review.action.kind === "create-pull-request" ||
            review.action.kind === "transition-issue") && (
            <div className="mb-4 space-y-2 rounded-xl border border-border bg-surface-subtle/40 p-4 text-xs leading-6">
              <p className="font-semibold">
                {review.action.kind === "create-pull-request"
                  ? l("Pull request review", "Revisión del pull request")
                  : l(
                      "Jira issue transition review",
                      "Revisión de transición Jira",
                    )}
              </p>
              <p>
                {review.action.kind === "create-pull-request"
                  ? l("Repository", "Repositorio")
                  : l("Project", "Proyecto")}
                : {destination?.name ?? destinationId} · {destinationId}
              </p>
              {review.action.kind === "create-pull-request" ? (
                <p>
                  {review.values.draft === true
                    ? l(
                        "Create as a draft pull request",
                        "Crear como pull request en borrador",
                      )
                    : l(
                        "Create as an open pull request",
                        "Crear como pull request abierto",
                      )}
                </p>
              ) : (
                <>
                  <p>
                    {l("Issue", "Incidencia")}: {review.values.recordId} ·{" "}
                    {l("Current reported status", "Estado actual reportado")}:{" "}
                    {target?.status ?? "—"}
                  </p>
                  <p>
                    {l("Selected transition", "Transición elegida")}:{" "}
                    {reviewTransition
                      ? l(reviewTransition.label.en, reviewTransition.label.es)
                      : review.values.transitionId}{" "}
                    · {review.values.transitionId}
                  </p>
                  {typeof review.values.fields === "string" &&
                    review.values.fields && (
                      <p className="whitespace-pre-wrap wrap-break-word">
                        {l("Transition fields", "Campos de transición")}:{" "}
                        {review.values.fields}
                      </p>
                    )}
                </>
              )}
              <p className="text-muted-foreground">
                {props.adapter.mode === "demo"
                  ? l(
                      "Local preview. No repository or Jira account is changed.",
                      "Vista local. No se modifica ningún repositorio ni cuenta Jira.",
                    )
                  : l(
                      "The confirmed request uses this workspace’s connected account and permissions.",
                      "La solicitud confirmada usa la cuenta y los permisos conectados de este workspace.",
                    )}
              </p>
            </div>
          )}
          {review.action.kind === "map-fields" && (
            <div className="mb-4">
              <ul className="mb-4 space-y-2">
                {mapping.map((row) => (
                  <li key={`${row.source}:${row.target}`} className="text-xs">
                    {row.source} → {row.target}
                  </li>
                ))}
              </ul>
              <ProductDocumentValues values={mapped} />
            </div>
          )}
        </ProductReview>
      )}
    </div>
  );
}

function ProductDocumentValues({ values }: { values: IntegrationValues }) {
  const { l } = useLanguage();
  if (!Object.keys(values).length)
    return (
      <ProductEmpty>
        {l(
          "Choose a source record to preview mapped fields.",
          "Elige un registro fuente para revisar los campos mapeados.",
        )}
      </ProductEmpty>
    );
  return (
    <dl className="space-y-2">
      {Object.entries(values).map(([key, value]) => (
        <div key={key} className="rounded-lg border border-border p-3">
          <dt className="text-[11px] text-muted-foreground">{key}</dt>
          <dd className="mt-1 whitespace-pre-wrap wrap-break-word text-xs leading-6">
            {Array.isArray(value) ? value.join(", ") : String(value)}
          </dd>
        </div>
      ))}
    </dl>
  );
}

import type {
  IntegrationConnection,
  IntegrationRecord,
  IntegrationResult,
  IntegrationUpdate,
} from "../../lib/integrations/contracts";
import type { DataTableQuery } from "../../lib/data-query";

export type ProductDataUpdate =
  | { kind: "ignore" }
  | { kind: "scope-changed" }
  | { kind: "rows"; records: IntegrationRecord[] };

/**
 * Connection-wide result DTOs carry no query/page identity. They identify when
 * remote membership, sorting and totals need revalidation with the current query.
 */
export function productDataUpdate(
  update: IntegrationUpdate,
  connection: IntegrationConnection,
  resourceId: string,
): ProductDataUpdate {
  if (
    connection.status !== "connected" ||
    !connection.resourceIds.includes(resourceId)
  )
    return { kind: "ignore" };
  if (update.kind === "connection") {
    const next = update.connection;
    if (
      next.id !== connection.id ||
      next.integrationId !== connection.integrationId ||
      next.workspaceId !== connection.workspaceId
    )
      return { kind: "ignore" };
    const scope = (item: IntegrationConnection) =>
      JSON.stringify([
        item.status,
        item.providerOptionId,
        item.revision,
        [...item.resourceIds].sort(),
        [...item.grantedPermissions].sort(),
      ]);
    return scope(next) === scope(connection)
      ? { kind: "ignore" }
      : { kind: "scope-changed" };
  }
  if (update.kind !== "result") return { kind: "ignore" };
  const result = update.result;
  const records =
    result.kind === "record"
      ? [result.record]
      : result.kind === "records"
        ? result.records
        : undefined;
  if (!records) return { kind: "ignore" };
  const matching: IntegrationRecord[] = [];
  let unspecifiedResource = records.length === 0;
  let otherAuthorizedResource = false;
  for (const record of records) {
    const fields = record.fields ?? {};
    if (
      (fields.workspaceId !== undefined &&
        fields.workspaceId !== connection.workspaceId) ||
      (fields.connectionId !== undefined &&
        fields.connectionId !== connection.id) ||
      (fields.integrationId !== undefined &&
        fields.integrationId !== connection.integrationId)
    )
      continue;
    if (fields.resourceId === undefined) {
      unspecifiedResource = true;
      continue;
    }
    if (fields.resourceId === resourceId) matching.push(record);
    else if (
      typeof fields.resourceId === "string" &&
      connection.resourceIds.includes(fields.resourceId)
    )
      otherAuthorizedResource = true;
  }
  // An authenticated query can join several granted resources. A broad event
  // may invalidate that membership, but never identifies the current page.
  return matching.length || unspecifiedResource || otherAuthorizedResource
    ? { kind: "rows", records: matching }
    : { kind: "ignore" };
}

/** Prevent a slower query from replacing rows invalidated by a live update. */
export function createProductDataEpoch() {
  let value = 0;
  return {
    invalidate() {
      value += 1;
    },
    capture() {
      return value;
    },
    isCurrent(snapshot: number) {
      return snapshot === value;
    },
  };
}

/** Only a subscription bound to this exact server query may replace its page. */
export function productReportedDataPage(
  result: IntegrationResult,
  connection: IntegrationConnection,
  resourceId: string,
  query: DataTableQuery,
) {
  if (
    result.kind !== "records" ||
    connection.status !== "connected" ||
    !connection.resourceIds.includes(resourceId) ||
    result.records.length > query.pagination.pageSize ||
    result.total < result.records.length ||
    new Set(result.records.map((record) => record.id)).size !==
      result.records.length
  )
    return undefined;
  if (
    result.records.some((record) => {
      const fields = record.fields ?? {};
      return (
        (fields.workspaceId !== undefined &&
          fields.workspaceId !== connection.workspaceId) ||
        (fields.connectionId !== undefined &&
          fields.connectionId !== connection.id) ||
        (fields.integrationId !== undefined &&
          fields.integrationId !== connection.integrationId) ||
        (fields.resourceId !== undefined &&
          (typeof fields.resourceId !== "string" ||
            !connection.resourceIds.includes(fields.resourceId)))
      );
    })
  )
    return undefined;
  return result;
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { ColumnDef, RowSelectionState } from "@tanstack/react-table";
import { Pencil, RefreshCw, Save } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import { DataTable, type DataTableQuery } from "@/components/ui/data-table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { parseIntegrationUpdate } from "@/lib/integrations/validation";
import type {
  IntegrationRecord,
  IntegrationUpdate,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import {
  findProductAction,
  invalidProductField,
  optimisticProductRecord,
  parseProductFields,
  productActionValues,
  productQueryValues,
  rollbackProductRecord,
} from "./product-model";
import {
  ProductActionUnavailable,
  ProductDate,
  ProductDocumentPreview,
  ProductFields,
  ProductLabeledTextarea,
  ProductOperationFeedback,
  ProductPanel,
  ProductResourcePicker,
  ProductResult,
  ProductReview,
  ProductStatus,
  ProductValidation,
  useProductResources,
} from "./product-ui";
import {
  createProductDataEpoch,
  productDataUpdate,
  productReportedDataPage,
} from "./product-data-reactivity";
import { startProductSubscription } from "./product-subscription";

const initialQuery: DataTableQuery = {
  search: "",
  filters: [],
  sorting: [],
  pagination: { pageIndex: 0, pageSize: 10 },
};

export type ProductDataSubscription = {
  integrationId: string;
  connectionId: string;
  workspaceId: string;
  resourceId: string;
  actionId: string;
  query: DataTableQuery;
  values: IntegrationValues;
  querySignature: string;
  signal: AbortSignal;
  /** Complete, server-filtered and server-paginated page for this subscription. */
  onUpdate: (update: IntegrationUpdate) => void;
  onError: () => void;
};

export type ProductDataSubscribe = (
  subscription: ProductDataSubscription,
) => (() => void) | Promise<() => void>;

export function ProductDataWorkbench(
  props: IntegrationWorkbenchProps & { subscribeData?: ProductDataSubscribe },
) {
  const { l } = useLanguage();
  const { adapter, connection, definition, subscribeData } = props;
  const { workspaceId, signal: scopeSignal } = props.scope;
  const read = useIntegrationOperation(props);
  const write = useIntegrationOperation(props);
  const readRun = read.run;
  const readCancel = read.cancel;
  const writeCancel = write.cancel;
  const writeReset = write.reset;
  const resources = useProductResources(props);
  const queryAction = findProductAction(props.definition, "query");
  const saveAction = findProductAction(
    props.definition,
    "save-record",
    "update-record",
  );
  const canSave = Boolean(saveAction);
  const [resourceId, setResourceId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [query, setQuery] = useState<DataTableQuery>(initialQuery);
  const [readValues, setReadValues] = useState<IntegrationValues>({});
  const [records, setRecords] = useState<IntegrationRecord[]>([]);
  const [total, setTotal] = useState(0);
  const [selection, setSelection] = useState<RowSelectionState>({});
  const [base, setBase] = useState<IntegrationRecord | null>(null);
  const [draft, setDraft] = useState<IntegrationValues>({});
  const [fieldsText, setFieldsText] = useState("{}");
  const [review, setReview] = useState<IntegrationValues | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [refresh, setRefresh] = useState(0);
  const [reactive, setReactive] = useState(
    Boolean(props.subscribeData || props.adapter.subscribe),
  );
  const [reactiveRetry, setReactiveRetry] = useState(0);
  const [reactiveError, setReactiveError] = useState(false);
  const [reactiveAt, setReactiveAt] = useState<string | null>(null);
  const [scopeStale, setScopeStale] = useState(false);
  const [dataEpoch] = useState(createProductDataEpoch);
  const queryIdentity = JSON.stringify([query, readValues]);
  const subscriptionDispose = useRef<(() => void) | null>(null);
  const stopReactive = useCallback(() => {
    subscriptionDispose.current?.();
    subscriptionDispose.current = null;
  }, []);
  const allowed = props.connection.resourceIds.includes(resourceId);
  const cursorPages = useRef<{ key: string; pages: Record<number, string> }>({
    key: "",
    pages: {},
  });
  const mutationSequence = useRef(0);
  const statusField = saveAction?.fields.find((field) => field.id === "status");

  const load = useCallback(async () => {
    if (!queryAction || !allowed || scopeStale) return;
    const epoch = dataEpoch.capture();
    const cursorKey = JSON.stringify([
      resourceId,
      readValues,
      query.search,
      query.filters,
      query.sorting,
      query.pagination.pageSize,
    ]);
    if (cursorPages.current.key !== cursorKey)
      cursorPages.current = { key: cursorKey, pages: {} };
    const values = productActionValues(
      queryAction,
      {
        ...readValues,
        ...productQueryValues(query, resourceId),
        cursor:
          cursorPages.current.pages[query.pagination.pageIndex] ??
          readValues.cursor ??
          "",
      },
      resourceId,
    );
    if (invalidProductField(queryAction, values)) return;
    const result = await readRun(queryAction, values);
    if (!dataEpoch.isCurrent(epoch)) return;
    if (result?.kind === "records") {
      if (result.cursor)
        cursorPages.current.pages[query.pagination.pageIndex + 1] =
          result.cursor;
      setRecords(result.records);
      setTotal(result.total);
      setLoaded(true);
    } else if (result?.kind === "record") {
      setRecords([result.record]);
      setTotal(1);
      setLoaded(true);
    }
  }, [
    queryAction,
    allowed,
    scopeStale,
    dataEpoch,
    readValues,
    query,
    resourceId,
    readRun,
  ]);

  useEffect(() => {
    const timer = setTimeout(() => {
      void load();
    }, 250);
    return () => {
      clearTimeout(timer);
      readCancel();
    };
  }, [load, refresh, readCancel]);

  useEffect(() => {
    if (
      (!subscribeData && !adapter.subscribe) ||
      !reactive ||
      !allowed ||
      scopeStale ||
      !queryAction ||
      queryAction.requiredPermissions?.some(
        (permission) => !connection.grantedPermissions.includes(permission),
      )
    )
      return;
    const streamValues = productActionValues(
      queryAction,
      {
        ...readValues,
        ...productQueryValues(query, resourceId),
        cursor:
          cursorPages.current.pages[query.pagination.pageIndex] ??
          readValues.cursor ??
          "",
      },
      resourceId,
    );
    if (invalidProductField(queryAction, streamValues)) return;
    const seen = new Set<string>();
    setReactiveError(false);
    setReactiveAt(null);
    const dispose = startProductSubscription(
      (listener, signal) =>
        subscribeData
          ? subscribeData({
              integrationId: definition.id,
              connectionId: connection.id,
              workspaceId,
              resourceId,
              actionId: queryAction.id,
              query: structuredClone(query),
              values: structuredClone(streamValues),
              querySignature: JSON.stringify([
                definition.id,
                connection.id,
                connection.revision,
                connection.providerOptionId,
                workspaceId,
                [...connection.resourceIds].sort(),
                [...connection.grantedPermissions].sort(),
                resourceId,
                queryAction.id,
                queryIdentity,
                streamValues,
              ]),
              signal,
              onUpdate: listener,
              onError: () => {
                if (!signal.aborted) setReactiveError(true);
              },
            })
          : adapter.subscribe!(connection.id, listener, {
              workspaceId,
              signal,
            }),
      {
        signal: scopeSignal,
        onUpdate: (raw) => {
          let update;
          try {
            update = parseIntegrationUpdate(raw, definition, connection.id, {
              workspaceId,
              signal: scopeSignal,
            });
          } catch {
            setReactiveError(true);
            return;
          }
          const change = productDataUpdate(update, connection, resourceId);
          if (change.kind === "ignore") return;
          if (change.kind === "scope-changed") {
            dataEpoch.invalidate();
            readCancel();
            writeCancel();
            setScopeStale(true);
            setRecords([]);
            setTotal(0);
            setBase(null);
            setReview(null);
            setSelection({});
            return;
          }
          const signature = JSON.stringify(update);
          if (seen.has(signature)) return;
          const page =
            subscribeData &&
            update.kind === "result" &&
            update.result.kind === "records"
              ? productReportedDataPage(
                  update.result,
                  connection,
                  resourceId,
                  query,
                )
              : undefined;
          if (
            subscribeData &&
            update.kind === "result" &&
            update.result.kind === "records" &&
            !page
          ) {
            setReactiveError(true);
            return;
          }
          seen.add(signature);
          if (seen.size > 128) seen.delete(seen.values().next().value!);
          dataEpoch.invalidate();
          readCancel();
          if (page) {
            setRecords(page.records);
            setTotal(page.total);
            setLoaded(true);
            if (page.cursor)
              cursorPages.current.pages[query.pagination.pageIndex + 1] =
                page.cursor;
          } else {
            // Connection-wide events carry no query identity. They invalidate
            // this query and never patch a different filter, sort or page.
            setRefresh((value) => value + 1);
          }
          setReactiveAt(new Date().toISOString());
          setReactiveError(false);
        },
        onError: () => setReactiveError(true),
      },
    );
    subscriptionDispose.current = dispose;
    return () => {
      dispose();
      if (subscriptionDispose.current === dispose)
        subscriptionDispose.current = null;
    };
  }, [
    adapter,
    subscribeData,
    connection,
    definition,
    workspaceId,
    scopeSignal,
    resourceId,
    queryIdentity,
    query,
    readValues,
    queryAction,
    reactive,
    reactiveRetry,
    allowed,
    scopeStale,
    dataEpoch,
    readCancel,
    writeCancel,
  ]);

  const edit = useCallback(
    (record: IntegrationRecord) => {
      setBase(record);
      setDraft({
        name: record.name,
        status: record.status,
        description: record.description,
      });
      setFieldsText(JSON.stringify(record.fields ?? {}, null, 2));
      setSelection({ [record.id]: true });
      setReview(null);
      writeReset();
    },
    [writeReset, setBase, setDraft, setFieldsText, setSelection, setReview],
  );

  const columns = useMemo<ColumnDef<IntegrationRecord>[]>(
    () => [
      {
        accessorKey: "name",
        header: l("Record", "Registro"),
        cell: ({ row }) => (
          <div>
            <p className="font-medium">{row.original.name}</p>
            <p className="mt-1 text-[10px] text-muted-foreground">
              {row.original.id}
            </p>
          </div>
        ),
      },
      {
        accessorKey: "status",
        header: l("Status", "Estado"),
        cell: ({ row }) => (
          <ProductStatus
            value={
              row.original.updatedAt.startsWith("pending:")
                ? "pending"
                : row.original.status
            }
          />
        ),
      },
      { accessorKey: "type", header: l("Type", "Tipo") },
      {
        accessorKey: "updatedAt",
        header: l("Updated", "Actualizado"),
        cell: ({ row }) => <ProductDate value={row.original.updatedAt} />,
      },
      {
        id: "edit",
        header: l("Actions", "Acciones"),
        enableSorting: false,
        cell: ({ row }) => (
          <Button
            size="sm"
            variant="ghost"
            disabled={write.pending || !canSave}
            onClick={() => edit(row.original)}
            aria-label={`${l("Edit", "Editar")} ${row.original.name}`}
          >
            <Pencil />
            {l("Edit", "Editar")}
          </Button>
        ),
      },
    ],
    [l, canSave, write.pending, edit],
  );

  const parsed = parseProductFields(fieldsText);
  const prepared = productActionValues(
    saveAction,
    {
      ...draft,
      ...(base
        ? {
            id: base.id,
            recordId: base.id,
            expectedUpdatedAt: base.updatedAt,
            ...(base.fields?.revision !== undefined
              ? { revision: base.fields.revision }
              : {}),
          }
        : {}),
      fields: fieldsText,
    },
    resourceId,
  );
  const invalid = invalidProductField(saveAction, prepared);
  const latest = base
    ? records.find((record) => record.id === base.id)
    : undefined;
  const conflict = write.errorCode === "conflict";

  async function save() {
    if (
      !saveAction ||
      !base ||
      !review ||
      !parsed.ok ||
      write.pending ||
      scopeStale
    )
      return;
    const original = base;
    const marker = `pending:${props.connection.id}:${props.connection.revision}:${original.id}:${++mutationSequence.current}`;
    const optimistic = optimisticProductRecord(original, review, marker);
    setRecords((items) =>
      items.map((item) => (item.id === original.id ? optimistic : item)),
    );
    const result = await write.run(saveAction, review);
    if (result?.kind === "record" && result.record.id === original.id) {
      setRecords((items) =>
        items.map((item) => (item.id === original.id ? result.record : item)),
      );
      setBase(result.record);
      setDraft({
        name: result.record.name,
        status: result.record.status,
        description: result.record.description,
      });
      setFieldsText(JSON.stringify(result.record.fields ?? {}, null, 2));
      setReview(null);
      setRefresh((value) => value + 1);
    } else {
      setRecords((items) => rollbackProductRecord(items, original, marker));
      if (result) setReview(null);
    }
  }

  return (
    <div className="space-y-5">
      <ProductPanel
        title={l("Explore your data", "Explora tus datos")}
        description={l(
          "Search, filters, sorting and pages are applied by your connected data source.",
          "La fuente conectada aplica la búsqueda, los filtros, el orden y las páginas.",
        )}
      >
        {(props.subscribeData || props.adapter.subscribe) && (
          <div className="mb-4 space-y-3 rounded-xl border border-border bg-surface-subtle/40 p-3">
            <label className="flex min-h-11 items-center gap-3 text-xs">
              <Checkbox
                checked={reactive}
                onCheckedChange={(value) => {
                  if (!value) stopReactive();
                  setReactive(value);
                }}
                disabled={scopeStale}
              />
              {l("Follow reactive data", "Seguir datos reactivos")}
            </label>
            <p
              role="status"
              className="text-xs leading-6 text-muted-foreground"
            >
              {!reactive ? (
                l(
                  "Live updates paused. You can still refresh records.",
                  "Actualizaciones en vivo pausadas. Puedes actualizar los registros.",
                )
              ) : reactiveAt ? (
                <>
                  {l(
                    "Reactive update received",
                    "Actualización reactiva recibida",
                  )}{" "}
                  · <ProductDate value={reactiveAt} />
                </>
              ) : (
                l(
                  "Waiting for reactive rows from this connection.",
                  "Esperando filas reactivas de esta conexión.",
                )
              )}
            </p>
            {reactiveError && (
              <div
                role="alert"
                className="flex flex-wrap items-center gap-3 text-xs"
              >
                <p>
                  {l(
                    "The live update was unavailable or invalid. Refresh records or reconnect the live transport.",
                    "La actualización en vivo no estaba disponible o no era válida. Actualiza los registros o reconecta el transporte.",
                  )}
                </p>
                <Button
                  size="sm"
                  variant="outline"
                  disabled={scopeStale}
                  onClick={() => setReactiveRetry((value) => value + 1)}
                >
                  {l("Reconnect live data", "Reconectar datos en vivo")}
                </Button>
              </div>
            )}
          </div>
        )}
        {scopeStale && (
          <p
            role="alert"
            className="mb-4 rounded-xl border border-destructive/25 p-3 text-xs leading-6"
          >
            {l(
              "The connection scope changed. Reopen the connection before reading or changing records.",
              "El alcance de la conexión cambió. Vuelve a abrir la conexión antes de consultar o modificar registros.",
            )}
          </p>
        )}
        <div className="mb-4 grid gap-4 sm:grid-cols-2">
          <ProductResourcePicker
            {...resources}
            value={resourceId}
            onChange={(value) => {
              read.reset();
              write.reset();
              stopReactive();
              dataEpoch.invalidate();
              setReactiveAt(null);
              setResourceId(value);
              setRecords([]);
              setLoaded(false);
              setBase(null);
              setReview(null);
              setSelection({});
              setQuery(initialQuery);
            }}
            disabled={write.pending || scopeStale}
          />
          <label className="space-y-2 text-xs font-medium">
            {l("Status filter", "Filtro de estado")}
            <Input
              value={String(
                query.filters.find((filter) => filter.id === "status")?.value ??
                  "",
              )}
              placeholder={l("Any status", "Cualquier estado")}
              disabled={write.pending || scopeStale}
              onChange={(event) => {
                stopReactive();
                dataEpoch.invalidate();
                setQuery((current) => ({
                  ...current,
                  filters: event.target.value
                    ? [{ id: "status", value: event.target.value }]
                    : [],
                  pagination: { ...current.pagination, pageIndex: 0 },
                }));
              }}
            />
          </label>
        </div>
        <ProductFields
          action={queryAction}
          values={readValues}
          onChange={(values) => {
            stopReactive();
            dataEpoch.invalidate();
            setReadValues(values);
          }}
          disabled={write.pending || scopeStale}
          exclude={[
            "query",
            "search",
            "filter",
            "status",
            "page",
            "pageIndex",
            "pageSize",
            "limit",
            "offset",
            "sort",
            "order",
            "filters",
            "sorting",
            "queryState",
            "resourceId",
          ]}
        />
        <div className="my-4 flex justify-end">
          <Button
            variant="outline"
            loading={read.pending}
            disabled={!queryAction || !allowed || write.pending || scopeStale}
            onClick={() => setRefresh((value) => value + 1)}
          >
            <RefreshCw />
            {l("Refresh records", "Actualizar registros")}
          </Button>
        </div>
        <ProductActionUnavailable action={queryAction} />
        <DataTable
          mode="external"
          data={records}
          rowCount={total}
          columns={columns}
          query={query}
          onQueryChange={(value) => {
            if (!write.pending && !scopeStale) {
              stopReactive();
              dataEpoch.invalidate();
              setQuery(value);
            }
          }}
          rowSelection={selection}
          onRowSelectionChange={setSelection}
          pageSizeOptions={[5, 10, 25, 50]}
          columnVisibility
          loading={read.pending}
          error={read.error ?? undefined}
          onRetry={() => setRefresh((value) => value + 1)}
          labels={{
            search: l("Search records…", "Buscar registros…"),
            empty: l(
              loaded ? "No matching records" : "No records loaded",
              loaded
                ? "No hay registros coincidentes"
                : "No hay registros cargados",
            ),
            emptyDescription: l(
              "Choose an authorized source and adjust your query.",
              "Elige una fuente autorizada y ajusta la consulta.",
            ),
            previous: l("Previous page", "Página anterior"),
            next: l("Next page", "Página siguiente"),
            selectAll: l("Select this page", "Seleccionar esta página"),
            selectRow: l("Select record", "Seleccionar registro"),
            selected: l("selected", "seleccionados"),
            page: l("Page", "Página"),
            of: l("of", "de"),
            rows: l("records", "registros"),
            clear: l("Clear search", "Limpiar búsqueda"),
            error: l(
              "Could not load records",
              "No se pudieron cargar los registros",
            ),
            retry: l("Retry", "Reintentar"),
            loading: l("Loading records", "Cargando registros"),
            columns: l("Columns", "Columnas"),
            clearSelection: l("Clear selection", "Limpiar selección"),
            rowsPerPage: l("Records per page", "Registros por página"),
          }}
        />
        <div className="mt-3">
          <ProductOperationFeedback operation={read} />
        </div>
        {read.result && !["records", "record"].includes(read.result.kind) && (
          <ProductResult result={read.result} />
        )}
      </ProductPanel>
      {base && (
        <ProductPanel
          title={l("Edit record", "Editar registro")}
          description={
            <>
              {base.id} · {l("Base version", "Versión base")}:{" "}
              <ProductDate value={base.updatedAt} />
            </>
          }
        >
          <div className="grid gap-4 sm:grid-cols-2">
            <label className="space-y-2 text-xs font-medium">
              {l("Name", "Nombre")}
              <Input
                value={String(draft.name ?? "")}
                onChange={(event) => {
                  setReview(null);
                  setDraft({ ...draft, name: event.target.value });
                }}
                disabled={write.pending}
              />
            </label>
            <label className="space-y-2 text-xs font-medium">
              {l("Status", "Estado")}
              {statusField?.options?.length ? (
                <Select
                  aria-label={l("Status", "Estado")}
                  value={String(draft.status ?? "")}
                  options={statusField.options.map((option) => ({
                    value: option.value,
                    label: l(option.label.en, option.label.es),
                  }))}
                  onValueChange={(value) => {
                    setReview(null);
                    setDraft({ ...draft, status: value });
                  }}
                  disabled={write.pending}
                />
              ) : (
                <Input
                  value={String(draft.status ?? "")}
                  onChange={(event) => {
                    setReview(null);
                    setDraft({ ...draft, status: event.target.value });
                  }}
                  disabled={write.pending}
                />
              )}
            </label>
          </div>
          <div className="my-4">
            <ProductLabeledTextarea
              label={l("Description", "Descripción")}
              value={String(draft.description ?? "")}
              onChange={(event) => {
                setReview(null);
                setDraft({ ...draft, description: event.target.value });
              }}
              disabled={write.pending}
            />
          </div>
          <ProductFields
            action={saveAction}
            values={draft}
            onChange={(values) => {
              setReview(null);
              setDraft(values);
            }}
            disabled={write.pending}
            exclude={[
              "id",
              "recordId",
              "name",
              "status",
              "description",
              "fields",
              "resourceId",
              "revision",
              "expectedUpdatedAt",
            ]}
          />
          <div className="my-4">
            <ProductLabeledTextarea
              label={l(
                "Record fields · JSON object",
                "Campos del registro · Objeto JSON",
              )}
              value={fieldsText}
              spellCheck={false}
              className="font-mono text-xs"
              onChange={(event) => {
                setFieldsText(event.target.value);
                setReview(null);
              }}
              disabled={write.pending}
              aria-invalid={!parsed.ok}
            />
          </div>
          {!parsed.ok && (
            <p
              role="alert"
              className="mb-3 text-xs text-destructive-foreground"
            >
              {l(
                "Use valid JSON with text, numbers, booleans or lists of text.",
                "Usa JSON válido con texto, números, booleanos o listas de texto.",
              )}
            </p>
          )}
          <ProductValidation action={saveAction} values={prepared} />
          {conflict && (
            <div
              role="alert"
              className="mb-4 space-y-3 rounded-xl border border-primary/30 bg-accent/30 p-4"
            >
              <p className="text-xs leading-6">
                {l(
                  "Your draft is preserved. Refresh the records, compare the latest values, then choose a new base before retrying.",
                  "Tu borrador se conserva. Actualiza los registros, compara los valores actuales y elige una nueva base antes de reintentar.",
                )}
              </p>
              {latest && latest.updatedAt !== base.updatedAt && (
                <div className="grid gap-3 sm:grid-cols-2">
                  <div>
                    <p className="mb-1 text-xs font-semibold">
                      {l(
                        "Latest source values",
                        "Valores actuales de la fuente",
                      )}
                    </p>
                    <p className="text-xs leading-6">
                      {latest.name} · {latest.status}
                    </p>
                    <p className="text-xs leading-6">{latest.description}</p>
                  </div>
                  <div>
                    <p className="mb-1 text-xs font-semibold">
                      {l("Your draft", "Tu borrador")}
                    </p>
                    <p className="text-xs leading-6">
                      {String(draft.name)} · {String(draft.status)}
                    </p>
                    <p className="text-xs leading-6">
                      {String(draft.description)}
                    </p>
                  </div>
                </div>
              )}
              <div className="flex flex-wrap gap-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setRefresh((value) => value + 1)}
                  disabled={read.pending}
                >
                  {l("Reload source", "Recargar fuente")}
                </Button>
                <Button
                  size="sm"
                  disabled={!latest || latest.updatedAt === base.updatedAt}
                  onClick={() => {
                    if (latest) {
                      setBase(latest);
                      setReview(null);
                      write.reset();
                    }
                  }}
                >
                  {l(
                    "Keep edits, use latest base",
                    "Conservar cambios y usar base actual",
                  )}
                </Button>
              </div>
            </div>
          )}
          <div className="flex flex-wrap gap-2">
            <Button
              appearance="gradient"
              disabled={
                !saveAction ||
                !parsed.ok ||
                Boolean(invalid) ||
                write.pending ||
                conflict ||
                !String(draft.name ?? "").trim()
              }
              onClick={() => setReview(prepared)}
            >
              <Save />
              {l("Review changes", "Revisar cambios")}
            </Button>
            <Button
              variant="outline"
              disabled={write.pending}
              onClick={() => {
                setBase(null);
                setReview(null);
              }}
            >
              {l("Close editor", "Cerrar editor")}
            </Button>
          </div>
          <div className="mt-4">
            <ProductOperationFeedback operation={write} />
            <ProductActionUnavailable action={saveAction} />
          </div>
          {write.result && write.result.kind !== "record" && (
            <div className="mt-4">
              <ProductResult result={write.result} />
              <p className="mt-2 text-xs text-muted-foreground">
                {l(
                  "Refresh the source to confirm the stored version.",
                  "Actualiza la fuente para confirmar la versión guardada.",
                )}
              </p>
            </div>
          )}
        </ProductPanel>
      )}
      {review && saveAction && (
        <ProductReview
          action={saveAction}
          values={review}
          pending={write.pending}
          disabled={scopeStale}
          grantedPermissions={props.connection.grantedPermissions}
          onConfirm={() => {
            void save();
          }}
          onReject={() => setReview(null)}
        >
          <div className="mb-4">
            <p className="mb-2 text-xs font-semibold">
              {l("Record fields", "Campos del registro")}
            </p>
            <ProductDocumentPreview
              content={String(review.fields ?? "{}")}
              format="json"
            />
          </div>
        </ProductReview>
      )}
    </div>
  );
}

import type {
  IntegrationAction,
  IntegrationDocument,
} from "../../lib/integrations/contracts";

export function productDocumentFormats(action?: IntegrationAction) {
  const supported: IntegrationDocument["format"][] = [
    "markdown",
    "text",
    "json",
  ];
  const field = action?.fields.find((item) => item.id === "format");
  if (!field?.options?.length) return supported;
  return supported.filter((format) =>
    field.options!.some((option) => option.value === format),
  );
}

/** Empty serialized documents; consumer bindings still validate their SDK schema. */
export function productBlankDocument(
  action?: IntegrationAction,
  integrationId?: string,
): IntegrationDocument {
  const format = productDocumentFormats(action)[0] ?? "json";
  const json =
    integrationId === "lexical"
      ? {
          root: {
            children: [
              {
                children: [],
                direction: null,
                format: "",
                indent: 0,
                type: "paragraph",
                version: 1,
                textFormat: 0,
                textStyle: "",
              },
            ],
            direction: null,
            format: "",
            indent: 0,
            type: "root",
            version: 1,
          },
        }
      : integrationId === "blocknote"
        ? [{ type: "paragraph", props: {}, content: [], children: [] }]
        : {};
  return {
    id: "",
    title: "",
    content: format === "json" ? JSON.stringify(json, null, 2) : "",
    format,
    revision: 0,
    updatedAt: "",
  };
}

"use client";

import { useRef, useState, type ReactNode } from "react";
import { Bold, Heading2, List, Plus, RefreshCw, Save } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import type {
  IntegrationDocument,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import {
  findProductAction,
  invalidProductField,
  productActionValues,
} from "./product-model";
import {
  ProductActionUnavailable,
  ProductDate,
  ProductDocumentPreview,
  ProductFields,
  ProductOperationFeedback,
  ProductPanel,
  ProductRecordList,
  ProductResourcePicker,
  ProductResult,
  ProductReview,
  ProductValidation,
  useProductResources,
} from "./product-ui";
import {
  productBlankDocument,
  productDocumentFormats,
} from "./product-document-defaults";

export type ProductDocumentEditorProps = {
  value: IntegrationDocument;
  onChange: (
    value: Pick<IntegrationDocument, "title" | "content" | "format">,
  ) => void;
  disabled: boolean;
  locale: "en" | "es";
};
export type ProductEditorRenderer = (
  props: ProductDocumentEditorProps,
) => ReactNode;

export function ProductDocumentWorkbench(
  props: IntegrationWorkbenchProps & { renderEditor?: ProductEditorRenderer },
) {
  const { l, locale } = useLanguage();
  const read = useIntegrationOperation(props);
  const write = useIntegrationOperation(props);
  const resources = useProductResources(props);
  const queryAction = findProductAction(props.definition, "query");
  const saveAction = findProductAction(props.definition, "save-document");
  const [resourceId, setResourceId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [documentId, setDocumentId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [base, setBase] = useState<IntegrationDocument | null>(null);
  const [draft, setDraft] = useState<IntegrationDocument>(() =>
    productBlankDocument(saveAction, props.definition.id),
  );
  const [remote, setRemote] = useState<IntegrationDocument | null>(null);
  const [readValues, setReadValues] = useState<IntegrationValues>({});
  const [extra, setExtra] = useState<IntegrationValues>({});
  const [review, setReview] = useState<IntegrationValues | null>(null);
  const editor = useRef<HTMLTextAreaElement>(null);
  const dirty =
    !base ||
    ["title", "content", "format"].some(
      (key) =>
        draft[key as "title" | "content" | "format"] !==
        base[key as "title" | "content" | "format"],
    );
  let validJson = true;
  if (draft.format === "json") {
    try {
      JSON.parse(draft.content);
    } catch {
      validJson = false;
    }
  }
  const saveValues = productActionValues(
    saveAction,
    {
      ...extra,
      documentId: draft.id || documentId,
      id: draft.id || documentId,
      title: draft.title,
      content: draft.content,
      format: draft.format,
      revision: base?.revision ?? 0,
      expectedRevision: base?.revision ?? 0,
    },
    resourceId,
  );
  const blocked = write.pending || read.pending;

  function accept(document: IntegrationDocument) {
    setBase(document);
    setDraft(document);
    setDocumentId(document.id);
    setRemote(null);
    setReview(null);
    write.reset();
  }
  async function load(id = documentId) {
    if (!queryAction) return;
    const values = productActionValues(
      queryAction,
      { ...readValues, documentId: id, id, view: "document" },
      resourceId,
    );
    if (invalidProductField(queryAction, values)) return;
    const result = await read.run(queryAction, values);
    if (result?.kind === "document") {
      if (
        base?.id === result.document.id &&
        result.document.revision < base.revision
      )
        return;
      if (base && dirty) setRemote(result.document);
      else accept(result.document);
    }
  }
  function change(
    value: Pick<IntegrationDocument, "title" | "content" | "format">,
  ) {
    setDraft((previous) => ({ ...previous, ...value }));
    setReview(null);
  }
  function insert(prefix: string, suffix = "") {
    const start = editor.current?.selectionStart ?? draft.content.length;
    const end = editor.current?.selectionEnd ?? start;
    change({
      ...draft,
      content: `${draft.content.slice(0, start)}${prefix}${draft.content.slice(start, end)}${suffix}${draft.content.slice(end)}`,
    });
    requestAnimationFrame(() => {
      editor.current?.focus();
      editor.current?.setSelectionRange(
        start + prefix.length,
        end + prefix.length,
      );
    });
  }
  async function save() {
    if (!saveAction || !review) return;
    const result = await write.run(saveAction, review);
    if (result?.kind === "document") accept(result.document);
    else if (result) setReview(null);
  }

  return (
    <div className="space-y-5">
      <ProductPanel
        title={l("Document workspace", "Espacio de documentos")}
        description={l(
          "Edit Markdown, text or structured documents with a versioned save.",
          "Edita Markdown, texto o documentos estructurados con guardado por versión.",
        )}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <ProductResourcePicker
            {...resources}
            value={resourceId}
            onChange={(value) => {
              setResourceId(value);
              setDocumentId(value);
              setBase(null);
              setDraft(productBlankDocument(saveAction, props.definition.id));
              read.reset();
              write.reset();
              setRemote(null);
              setReview(null);
            }}
            disabled={blocked || Boolean(base && dirty)}
          />
          <label className="space-y-2 text-xs font-medium">
            {l("Document ID", "ID del documento")}
            <Input
              value={documentId}
              onChange={(event) => {
                setDocumentId(event.target.value);
                setReview(null);
              }}
              disabled={blocked}
              placeholder={l(
                "Open an existing document",
                "Abrir un documento existente",
              )}
            />
          </label>
        </div>
        <div className="mt-4">
          <ProductFields
            action={queryAction}
            values={readValues}
            onChange={setReadValues}
            exclude={["resourceId", "id", "documentId"]}
            disabled={blocked}
          />
        </div>
        <div className="my-4 flex flex-wrap gap-2">
          <Button
            variant="outline"
            loading={read.pending}
            disabled={!queryAction || write.pending}
            onClick={() => {
              void load();
            }}
          >
            <RefreshCw />
            {l("Load document", "Cargar documento")}
          </Button>
          <Button
            variant="outline"
            disabled={blocked || Boolean(base && dirty)}
            onClick={() => {
              setBase(null);
              setDraft(productBlankDocument(saveAction, props.definition.id));
              setDocumentId("");
              setRemote(null);
              setReview(null);
              write.reset();
            }}
          >
            <Plus />
            {l("New document", "Nuevo documento")}
          </Button>
          {base && (
            <p className="self-center text-[11px] text-muted-foreground">
              {l("Revision", "Revisión")} {base.revision} ·{" "}
              <ProductDate value={base.updatedAt} />
            </p>
          )}
        </div>
        <ProductActionUnavailable action={queryAction} />
        <ProductOperationFeedback operation={read} />
        {read.result?.kind === "records" && (
          <ProductRecordList
            records={read.result.records}
            onSelect={(record) => {
              setDocumentId(record.id);
              void load(record.id);
            }}
            selected={base?.id}
          />
        )}
      </ProductPanel>
      <div className="grid items-start gap-5 xl:grid-cols-2">
        <ProductPanel
          title={l("Editor", "Editor")}
          description={
            dirty
              ? l("Unsaved changes", "Cambios sin guardar")
              : l(
                  "Matches the stored revision",
                  "Coincide con la versión guardada",
                )
          }
        >
          {props.renderEditor ? (
            props.renderEditor({
              value: draft,
              onChange: change,
              disabled: blocked,
              locale,
            })
          ) : (
            <div className="space-y-4">
              <label className="block space-y-2 text-xs font-medium">
                {l("Title", "Título")}
                <Input
                  value={draft.title}
                  onChange={(event) =>
                    change({ ...draft, title: event.target.value })
                  }
                  disabled={blocked}
                />
              </label>
              <Select
                label={l("Document format", "Formato del documento")}
                value={draft.format}
                onValueChange={(value) =>
                  change({
                    ...draft,
                    format: value as IntegrationDocument["format"],
                  })
                }
                options={[
                  { value: "markdown", label: "Markdown" },
                  { value: "text", label: l("Plain text", "Texto") },
                  {
                    value: "json",
                    label: l("Structured JSON", "JSON estructurado"),
                  },
                ].filter((option) =>
                  productDocumentFormats(saveAction).includes(
                    option.value as IntegrationDocument["format"],
                  ),
                )}
                disabled={blocked}
              />
              {draft.format === "markdown" && (
                <div
                  role="toolbar"
                  aria-label={l("Formatting", "Formato")}
                  className="flex flex-wrap gap-2"
                >
                  <Button
                    size="sm"
                    variant="outline"
                    aria-label={l("Bold", "Negrita")}
                    disabled={blocked}
                    onClick={() => insert("**", "**")}
                  >
                    <Bold />
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    aria-label={l("Heading", "Encabezado")}
                    disabled={blocked}
                    onClick={() => insert("\n## ")}
                  >
                    <Heading2 />
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    aria-label={l("List item", "Elemento de lista")}
                    disabled={blocked}
                    onClick={() => insert("\n- ")}
                  >
                    <List />
                  </Button>
                </div>
              )}
              <label className="block space-y-2 text-xs font-medium">
                {l("Document content", "Contenido del documento")}
                <Textarea
                  ref={editor}
                  value={draft.content}
                  onChange={(event) =>
                    change({ ...draft, content: event.target.value })
                  }
                  className="min-h-72 font-mono text-xs"
                  disabled={blocked}
                  aria-invalid={!validJson}
                  spellCheck={draft.format !== "json"}
                />
              </label>
            </div>
          )}
          {!validJson && (
            <p
              role="alert"
              className="mt-3 text-xs text-destructive-foreground"
            >
              {l(
                "Correct the JSON syntax before saving.",
                "Corrige la sintaxis JSON antes de guardar.",
              )}
            </p>
          )}
          <div className="my-4">
            <ProductFields
              action={saveAction}
              values={extra}
              onChange={(value) => {
                setExtra(value);
                setReview(null);
              }}
              exclude={[
                "resourceId",
                "id",
                "documentId",
                "title",
                "content",
                "format",
                "revision",
                "expectedRevision",
              ]}
              disabled={blocked}
            />
          </div>
          <ProductValidation action={saveAction} values={saveValues} />
          <div className="mt-4 flex flex-wrap gap-2">
            <Button
              appearance="gradient"
              disabled={
                !saveAction ||
                blocked ||
                !draft.title.trim() ||
                !validJson ||
                Boolean(invalidProductField(saveAction, saveValues)) ||
                write.errorCode === "conflict"
              }
              onClick={() => setReview(saveValues)}
            >
              <Save />
              {l("Review and save", "Revisar y guardar")}
            </Button>
            {base && (
              <Button
                variant="outline"
                disabled={blocked}
                onClick={() => accept(base)}
              >
                {l("Discard local changes", "Descartar cambios locales")}
              </Button>
            )}
          </div>
          <div className="mt-4">
            <ProductActionUnavailable action={saveAction} />
            <ProductOperationFeedback operation={write} />
          </div>
          {write.result && write.result.kind !== "document" && (
            <div className="mt-4">
              <ProductResult result={write.result} />
              <p className="mt-2 text-xs text-muted-foreground">
                {l(
                  "Reload to confirm the stored document revision.",
                  "Recarga para confirmar la versión del documento guardado.",
                )}
              </p>
            </div>
          )}
        </ProductPanel>
        <ProductPanel title={l("Preview", "Vista previa")}>
          <ProductDocumentPreview
            content={draft.content}
            format={draft.format}
          />
        </ProductPanel>
      </div>
      {(remote || write.errorCode === "conflict") && (
        <ProductPanel
          title={l(
            "Resolve a document conflict",
            "Resolver un conflicto de documento",
          )}
        >
          <p className="mb-4 text-xs leading-6">
            {l(
              "Your edits are preserved. Load the latest revision and compare it before choosing which version to keep.",
              "Tus cambios se conservan. Carga la versión actual y compárala antes de elegir qué versión conservar.",
            )}
          </p>
          {remote && (
            <div className="mb-4">
              <p className="mb-3 text-xs font-medium">
                {remote.title} · {l("Revision", "Revisión")} {remote.revision}
              </p>
              <ProductDocumentPreview
                content={remote.content}
                format={remote.format}
              />
            </div>
          )}
          <div className="flex flex-wrap gap-2">
            <Button
              variant="outline"
              loading={read.pending}
              onClick={() => {
                void load(base?.id ?? documentId);
              }}
            >
              {l("Load latest revision", "Cargar versión actual")}
            </Button>
            {remote && (
              <>
                <Button variant="outline" onClick={() => accept(remote)}>
                  {l("Use remote content", "Usar contenido remoto")}
                </Button>
                <Button
                  appearance="gradient"
                  onClick={() => {
                    setBase(remote);
                    setDraft((value) => ({
                      ...value,
                      id: remote.id,
                      revision: remote.revision,
                    }));
                    setDocumentId(remote.id);
                    setRemote(null);
                    setReview(null);
                    write.reset();
                  }}
                >
                  {l(
                    "Keep edits, use latest revision",
                    "Conservar cambios y usar revisión actual",
                  )}
                </Button>
              </>
            )}
          </div>
        </ProductPanel>
      )}
      {review && saveAction && (
        <ProductReview
          action={saveAction}
          values={review}
          pending={write.pending}
          grantedPermissions={props.connection.grantedPermissions}
          onConfirm={() => {
            void save();
          }}
          onReject={() => setReview(null)}
        />
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { FileUp, RefreshCw, Search, ThumbsUp, Trash2 } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import type {
  IntegrationAction,
  IntegrationJob,
  IntegrationRecord,
  IntegrationResult,
  IntegrationSearchHit,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import {
  findProductAction,
  invalidProductField,
  mergeProductRecords,
  productActionValues,
} from "./product-model";
import {
  ProductActionUnavailable,
  ProductEmpty,
  ProductFields,
  ProductJobResult,
  ProductLabeledTextarea,
  ProductOperationFeedback,
  ProductPanel,
  ProductResourcePicker,
  ProductResult,
  ProductReview,
  ProductSearchResults,
  ProductStatus,
  ProductValidation,
  useProductResources,
} from "./product-ui";
import {
  productReportedRemoval,
  productSourceRemovalResult,
  type ProductSourceRemoval,
} from "./product-source-removal";

export function ProductKnowledgeWorkbench(props: IntegrationWorkbenchProps) {
  const { l, locale } = useLanguage();
  const read = useIntegrationOperation(props);
  const readRun = read.run;
  const readPending = read.pending;
  const upload = useIntegrationOperation(props);
  const ingest = useIntegrationOperation(props);
  const search = useIntegrationOperation(props);
  const evaluate = useIntegrationOperation(props);
  const remove = useIntegrationOperation(props);
  const resources = useProductResources(props);
  const queryAction = findProductAction(props.definition, "query");
  const ingestAction = findProductAction(props.definition, "ingest");
  const searchAction = findProductAction(props.definition, "search");
  const evaluateAction = findProductAction(props.definition, "evaluate");
  const cancelAction = findProductAction(props.definition, "cancel-job");
  const deleteAction = findProductAction(props.definition, "delete-source");
  const [resourceId, setResourceId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [file, setFile] = useState<File | null>(null);
  const [uploadReview, setUploadReview] = useState<{
    file: File;
    alt: string;
  } | null>(null);
  const [sourceName, setSourceName] = useState("");
  const [sourceUrl, setSourceUrl] = useState("");
  const [sourceContent, setSourceContent] = useState("");
  const [asset, setAsset] = useState<Extract<
    IntegrationResult,
    { kind: "upload" }
  > | null>(null);
  const [sources, setSources] = useState<IntegrationRecord[]>([]);
  const [indexStatus, setIndexStatus] = useState<string | null>(null);
  const [job, setJob] = useState<IntegrationJob | null>(null);
  const [follow, setFollow] = useState(false);
  const [query, setQuery] = useState("");
  const [searchedQuery, setSearchedQuery] = useState("");
  const [hits, setHits] = useState<IntegrationSearchHit[]>([]);
  const [selectedHit, setSelectedHit] = useState("");
  const [rating, setRating] = useState("relevant");
  const [feedback, setFeedback] = useState("");
  const [extra, setExtra] = useState<IntegrationValues>({});
  const [selectedSourceId, setSelectedSourceId] = useState("");
  const [removal, setRemoval] = useState<ProductSourceRemoval | null>(null);
  const [review, setReview] = useState<{
    action: IntegrationAction;
    values: IntegrationValues;
    operation: "ingest" | "evaluate" | "cancel" | "delete";
    source?: IntegrationRecord;
  } | null>(null);
  const selectedSource = sources.find(
    (source) => source.id === selectedSourceId,
  );
  const removalActive = Boolean(
    removal &&
    ["submitted", "pending", "awaiting-status"].includes(removal.phase),
  );

  const accept = useCallback(
    (result: IntegrationResult | null, deletionSourceId?: string) => {
      if (!result) return;
      if (result?.kind === "knowledge") {
        setSources(result.documents);
        setIndexStatus(result.status);
      }
      if (result?.kind === "records") setSources(result.records);
      if (result.kind === "record")
        setSources((current) => mergeProductRecords(current, [result.record]));
      if (["knowledge", "records", "record"].includes(result.kind)) {
        setRemoval((current) =>
          current ? productSourceRemovalResult(current, result) : null,
        );
      }
      if (result?.kind === "job") {
        if (deletionSourceId) {
          setRemoval((current) =>
            current?.sourceId === deletionSourceId
              ? productSourceRemovalResult(current, result)
              : current,
          );
          return;
        }
        setJob(result.job);
        if (["completed", "failed", "cancelled"].includes(result.job.status))
          setFollow(false);
      }
      if (result.kind === "receipt" && deletionSourceId) {
        setRemoval((current) =>
          current?.sourceId === deletionSourceId
            ? productSourceRemovalResult(current, result)
            : current,
        );
      }
    },
    [setSources, setIndexStatus, setRemoval, setJob, setFollow],
  );
  const refresh = useCallback(async () => {
    if (!queryAction || readPending) return;
    const values = productActionValues(
      queryAction,
      {
        ...extra,
        view: removalActive ? "deletion" : job ? "ingestion" : "sources",
        jobId: removalActive ? (removal?.job?.id ?? "") : (job?.id ?? ""),
        ...(removalActive && removal
          ? {
              sourceId: removal.sourceId,
              documentId: removal.sourceId,
              recordId: removal.sourceId,
            }
          : {}),
      },
      resourceId,
    );
    if (invalidProductField(queryAction, values)) return;
    accept(
      await readRun(queryAction, values),
      removalActive ? removal?.sourceId : undefined,
    );
  }, [
    queryAction,
    readPending,
    readRun,
    extra,
    job,
    resourceId,
    removalActive,
    removal,
    accept,
  ]);
  useEffect(() => {
    if (
      removalActive ||
      !follow ||
      !job ||
      !["queued", "running"].includes(job.status)
    )
      return;
    const timer = setInterval(() => {
      if (document.visibilityState === "visible") void refresh();
    }, 5000);
    return () => clearInterval(timer);
  }, [follow, job, refresh, removalActive]);

  async function uploadSource() {
    if (!uploadReview || upload.pending) return;
    const result = await upload.upload(uploadReview.file, uploadReview.alt);
    if (result?.kind === "upload") {
      setAsset(result);
      setUploadReview(null);
    }
  }
  function stage(
    action: IntegrationAction | undefined,
    values: IntegrationValues,
    operation: "ingest" | "evaluate" | "cancel" | "delete",
  ) {
    if (!action) return;
    const prepared = productActionValues(
      action,
      { ...extra, ...values },
      resourceId,
    );
    if (
      operation === "delete" &&
      (!selectedSource || productReportedRemoval(selectedSource) === "deleted")
    )
      return;
    if (!invalidProductField(action, prepared))
      setReview({
        action,
        values: prepared,
        operation,
        ...(operation === "delete" ? { source: selectedSource } : {}),
      });
  }
  async function submit() {
    if (!review) return;
    if (review.operation === "delete") {
      if (remove.pending || read.pending || removalActive) return;
      const source = sources.find((item) => item.id === review.source?.id);
      if (
        !source ||
        source.updatedAt !== review.source?.updatedAt ||
        productReportedRemoval(source) === "deleted"
      )
        return;
      read.cancel();
      search.cancel();
      setFollow(false);
      const pending: ProductSourceRemoval = {
        sourceId: source.id,
        name: source.name,
        source,
        phase: "submitted",
      };
      setRemoval(pending);
      const result = await remove.run(review.action, review.values);
      if (result) {
        accept(result, source.id);
        setReview(null);
        setHits([]);
        setSelectedHit("");
        setSearchedQuery("");
      } else {
        setRemoval((current) =>
          current?.sourceId === source.id && current.phase === "submitted"
            ? { ...current, phase: "unconfirmed" }
            : current,
        );
      }
      return;
    }
    const operation = review.operation === "evaluate" ? evaluate : ingest;
    const result = await operation.run(review.action, review.values);
    if (!result) return;
    accept(result);
    if (review.operation === "evaluate") setFeedback("");
    setReview(null);
  }
  async function searchSources() {
    if (!searchAction || !query.trim()) return;
    const values = productActionValues(
      searchAction,
      { ...extra, query },
      resourceId,
    );
    if (invalidProductField(searchAction, values)) return;
    const result = await search.run(searchAction, values);
    if (result?.kind === "knowledge" || result?.kind === "search") {
      setHits(result.hits);
      setSearchedQuery(query);
      setSelectedHit("");
      setReview(null);
      if (result.kind === "knowledge") accept(result);
    }
  }
  const ingestValues = productActionValues(
    ingestAction,
    {
      ...extra,
      assetId: asset?.asset.id ?? "",
      sourceId: asset?.asset.id ?? resourceId,
      sourceRef: asset?.asset.id || sourceUrl || resourceId,
      source: sourceUrl || asset?.asset.id || resourceId,
      url: sourceUrl,
      title: sourceName || asset?.asset.name || "",
      name: sourceName || asset?.asset.name || "",
      content: sourceContent,
    },
    resourceId,
  );
  const evaluationValues = productActionValues(
    evaluateAction,
    {
      ...extra,
      hitId: selectedHit,
      sourceId: hits.find((hit) => hit.id === selectedHit)?.source ?? "",
      query: searchedQuery,
      rating,
      feedback,
      comment: feedback,
    },
    resourceId,
  );
  const deletionValues = productActionValues(
    deleteAction,
    {
      ...extra,
      sourceId: selectedSource?.id ?? "",
      sourceRef: selectedSource?.id ?? "",
      documentId: selectedSource?.id ?? "",
      recordId: selectedSource?.id ?? "",
      id: selectedSource?.id ?? "",
      expectedUpdatedAt: selectedSource?.updatedAt ?? "",
    },
    resourceId,
  );
  const reviewSourceCurrent =
    review?.operation !== "delete" ||
    Boolean(
      review.source &&
      selectedSource &&
      review.source.id === selectedSource.id &&
      review.source.updatedAt === selectedSource.updatedAt &&
      productReportedRemoval(selectedSource) !== "deleted",
    );

  return (
    <div className="space-y-5">
      <ProductPanel
        title={l("Knowledge sources", "Fuentes de conocimiento")}
        description={l(
          "Inspect the access and indexing status reported for your selected source.",
          "Revisa el acceso y el estado de indexación reportados para tu fuente seleccionada.",
        )}
      >
        <ProductResourcePicker
          {...resources}
          value={resourceId}
          onChange={(value) => {
            [read, upload, ingest, search, evaluate, remove].forEach(
              (operation) => operation.reset(),
            );
            setResourceId(value);
            setSources([]);
            setHits([]);
            setAsset(null);
            setUploadReview(null);
            setJob(null);
            setReview(null);
            setIndexStatus(null);
            setFollow(false);
            setSelectedSourceId("");
            setRemoval(null);
          }}
          disabled={
            ingest.pending ||
            upload.pending ||
            evaluate.pending ||
            remove.pending ||
            removalActive
          }
        />
        <div className="mt-4">
          <ProductFields
            action={queryAction}
            values={extra}
            onChange={(value) => {
              setExtra(value);
              setReview(null);
            }}
            exclude={["resourceId", "view", "jobId"]}
          />
        </div>
        <div className="my-4 flex flex-wrap items-center gap-3">
          <Button
            variant="outline"
            loading={read.pending}
            disabled={!queryAction || remove.pending}
            onClick={() => {
              void refresh();
            }}
          >
            <RefreshCw />
            {l("Refresh sources and access", "Actualizar fuentes y acceso")}
          </Button>
          {indexStatus && <ProductStatus value={indexStatus} />}
        </div>
        {sources.length ? (
          <ul
            className="space-y-3"
            aria-label={l(
              "Reported knowledge sources",
              "Fuentes de conocimiento reportadas",
            )}
          >
            {sources.map((source) => (
              <li
                key={source.id}
                className="rounded-xl border border-border bg-surface-subtle/30 p-4"
              >
                <div className="flex flex-wrap items-start justify-between gap-3">
                  <div className="min-w-0">
                    <p className="text-xs font-semibold">{source.name}</p>
                    <p className="mt-1 text-xs leading-6 text-muted-foreground">
                      {source.description}
                    </p>
                    <p className="mt-2 text-[10px] text-muted-foreground">
                      {source.id}
                    </p>
                  </div>
                  <KnowledgeSourceStatus source={source} />
                </div>
                {deleteAction && (
                  <Button
                    size="sm"
                    variant="outline"
                    className="mt-3"
                    disabled={
                      remove.pending ||
                      removalActive ||
                      productReportedRemoval(source) === "deleted"
                    }
                    aria-pressed={selectedSourceId === source.id}
                    onClick={() => {
                      setSelectedSourceId(source.id);
                      setReview(null);
                    }}
                  >
                    {l("Select source", "Seleccionar fuente")} · {source.name}
                  </Button>
                )}
              </li>
            ))}
          </ul>
        ) : (
          <ProductEmpty>
            {l(
              "Refresh to load sources and their reported access status.",
              "Actualiza para cargar fuentes y su acceso reportado.",
            )}
          </ProductEmpty>
        )}
        <div className="mt-3">
          <ProductOperationFeedback operation={read} />
          <ProductActionUnavailable action={queryAction} />
        </div>
      </ProductPanel>
      <ProductPanel
        title={l(
          "Remove a knowledge source",
          "Eliminar una fuente de conocimiento",
        )}
        description={l(
          "Choose a known source and review its removal. Deletion remains pending until your connected service reports its outcome.",
          "Elige una fuente conocida y revisa su eliminación. Quedará pendiente hasta que el servicio conectado informe el resultado.",
        )}
      >
        <div className="space-y-4">
          <Select
            label={l("Source to remove", "Fuente a eliminar")}
            value={selectedSourceId}
            options={sources.map((source) => ({
              value: source.id,
              label: source.name,
              disabled: productReportedRemoval(source) === "deleted",
            }))}
            onValueChange={(value) => {
              setSelectedSourceId(value);
              setReview(null);
            }}
            disabled={remove.pending || read.pending || removalActive}
          />
          {selectedSource && (
            <div className="rounded-xl bg-surface-subtle p-3">
              <p className="text-xs font-semibold">{selectedSource.name}</p>
              <p className="my-2 text-xs text-muted-foreground">
                {selectedSource.id}
              </p>
              <KnowledgeSourceStatus source={selectedSource} />
            </div>
          )}
          <ProductFields
            action={deleteAction}
            values={extra}
            onChange={(value) => {
              setExtra(value);
              setReview(null);
            }}
            exclude={[
              "resourceId",
              "sourceId",
              "sourceRef",
              "documentId",
              "recordId",
              "id",
              "expectedUpdatedAt",
            ]}
            disabled={remove.pending || removalActive}
          />
          <ProductValidation action={deleteAction} values={deletionValues} />
          <Button
            variant="outline"
            disabled={
              !deleteAction ||
              !selectedSource ||
              remove.pending ||
              read.pending ||
              removalActive ||
              productReportedRemoval(selectedSource) === "deleted" ||
              Boolean(invalidProductField(deleteAction, deletionValues))
            }
            onClick={() => stage(deleteAction, deletionValues, "delete")}
          >
            <Trash2 />
            {l("Review source removal", "Revisar eliminación de fuente")}
          </Button>
          <ProductActionUnavailable action={deleteAction} />
          <ProductOperationFeedback operation={remove} />
          {removal && (
            <div
              className="space-y-4 rounded-xl border border-border p-4"
              role="status"
            >
              <p className="text-xs font-semibold">{removal.name}</p>
              <KnowledgeRemovalStatus removal={removal} />
              {removal.source && (
                <KnowledgeSourceStatus source={removal.source} />
              )}
              {removal.job && removal.phase !== "deleted" && (
                <div className="space-y-3">
                  <p className="text-[11px] text-muted-foreground">
                    {l(
                      "Last reported deletion job",
                      "Último trabajo de eliminación reportado",
                    )}
                  </p>
                  <ProductJobResult job={removal.job} />
                </div>
              )}
              {removal.receipt && <ProductResult result={removal.receipt} />}
              <Button
                variant="outline"
                loading={read.pending}
                disabled={!queryAction || remove.pending}
                onClick={() => {
                  void refresh();
                }}
              >
                <RefreshCw />
                {l(
                  "Refresh deletion status",
                  "Actualizar estado de eliminación",
                )}
              </Button>
            </div>
          )}
        </div>
      </ProductPanel>
      <div className="grid items-start gap-5 xl:grid-cols-2">
        <ProductPanel
          title={l("Add and ingest a source", "Añadir e ingerir una fuente")}
        >
          <div className="space-y-4">
            <label className="block space-y-2 text-xs font-medium">
              {l("Source name", "Nombre de la fuente")}
              <Input
                value={sourceName}
                onChange={(event) => {
                  setSourceName(event.target.value);
                  setUploadReview(null);
                  setReview(null);
                }}
              />
            </label>
            <label className="block space-y-2 text-xs font-medium">
              {l("Source file", "Archivo de la fuente")}
              <Input
                type="file"
                accept=".pdf,.txt,.md,.markdown,.csv,.json,.docx"
                onChange={(event) => {
                  setFile(event.target.files?.[0] ?? null);
                  setAsset(null);
                  setUploadReview(null);
                  setReview(null);
                  upload.reset();
                }}
                disabled={upload.pending || ingest.pending}
              />
            </label>
            <Button
              variant="outline"
              loading={upload.pending}
              disabled={!file || ingest.pending}
              onClick={() => {
                if (file)
                  setUploadReview({ file, alt: sourceName || file.name });
              }}
            >
              <FileUp />
              {l("Review source upload", "Revisar subida de fuente")}
            </Button>
            {uploadReview && (
              <div className="space-y-3 rounded-xl border border-primary/30 bg-accent/30 p-4">
                <p className="text-xs font-semibold">
                  {uploadReview.file.name}
                </p>
                <p className="text-xs text-muted-foreground">
                  {uploadReview.file.size.toLocaleString(
                    locale === "es" ? "es-CO" : "en-US",
                  )}{" "}
                  {l("bytes", "bytes")} ·{" "}
                  {uploadReview.file.type ||
                    l(
                      "Unspecified file type",
                      "Tipo de archivo sin especificar",
                    )}
                </p>
                <p className="text-xs">{uploadReview.alt}</p>
                <div className="flex flex-wrap gap-2">
                  <Button
                    appearance="gradient"
                    loading={upload.pending}
                    onClick={() => {
                      void uploadSource();
                    }}
                  >
                    {l("Confirm upload", "Confirmar subida")}
                  </Button>
                  <Button
                    variant="outline"
                    disabled={upload.pending}
                    onClick={() => setUploadReview(null)}
                  >
                    {l("Back to editing", "Volver a editar")}
                  </Button>
                </div>
              </div>
            )}
            <ProductOperationFeedback operation={upload} />
            {asset && (
              <div className="rounded-xl bg-accent/40 p-3">
                <ProductResult result={asset} />
              </div>
            )}
            <label className="block space-y-2 text-xs font-medium">
              {l("Or source URL", "O URL de la fuente")}
              <Input
                type="url"
                value={sourceUrl}
                onChange={(event) => {
                  setSourceUrl(event.target.value);
                  setReview(null);
                }}
              />
            </label>
            <ProductLabeledTextarea
              label={l("Source content", "Contenido de la fuente")}
              value={sourceContent}
              onChange={(event) => {
                setSourceContent(event.target.value);
                setReview(null);
              }}
              disabled={ingest.pending}
            />
            <ProductFields
              action={ingestAction}
              values={extra}
              onChange={(value) => {
                setExtra(value);
                setReview(null);
              }}
              exclude={[
                "resourceId",
                "sourceId",
                "sourceRef",
                "assetId",
                "source",
                "url",
                "title",
                "name",
                "content",
              ]}
              disabled={ingest.pending}
            />
            <ProductValidation action={ingestAction} values={ingestValues} />
            <Button
              appearance="gradient"
              disabled={
                !ingestAction ||
                (!asset && !sourceUrl.trim() && !sourceContent.trim()) ||
                ingest.pending ||
                Boolean(invalidProductField(ingestAction, ingestValues))
              }
              onClick={() => stage(ingestAction, ingestValues, "ingest")}
            >
              {l("Review ingestion", "Revisar ingestión")}
            </Button>
            <ProductActionUnavailable action={ingestAction} />
            <ProductOperationFeedback operation={ingest} />
          </div>
        </ProductPanel>
        <ProductPanel title={l("Ingestion progress", "Progreso de ingestión")}>
          {job ? (
            <>
              <ProductJobResult job={job} />
              <div className="mt-4 flex flex-wrap items-center gap-3">
                <label className="flex min-h-11 items-center gap-2 text-xs">
                  <Checkbox
                    checked={follow}
                    onCheckedChange={setFollow}
                    disabled={
                      !queryAction ||
                      removalActive ||
                      !["queued", "running"].includes(job.status)
                    }
                  />
                  {l(
                    "Refresh progress every 5 seconds",
                    "Actualizar progreso cada 5 segundos",
                  )}
                </label>
                {cancelAction && (
                  <Button
                    variant="outline"
                    disabled={
                      ingest.pending ||
                      !["queued", "running"].includes(job.status)
                    }
                    onClick={() =>
                      stage(
                        cancelAction,
                        { jobId: job.id, id: job.id },
                        "cancel",
                      )
                    }
                  >
                    {l("Review job cancellation", "Revisar cancelación")}
                  </Button>
                )}
              </div>
            </>
          ) : ingest.result ? (
            <ProductResult result={ingest.result} />
          ) : (
            <ProductEmpty>
              {l(
                "Start ingestion to see the returned steps, progress and execution log.",
                "Inicia la ingestión para ver sus pasos, progreso y registro de ejecución.",
              )}
            </ProductEmpty>
          )}
          {job && ingest.result && ingest.result.kind !== "job" && (
            <div className="mt-4">
              <ProductResult result={ingest.result} />
            </div>
          )}
        </ProductPanel>
      </div>
      <ProductPanel title={l("Search with citations", "Buscar con citas")}>
        <form
          className="mb-5 space-y-4"
          onSubmit={(event) => {
            event.preventDefault();
            void searchSources();
          }}
        >
          <label className="block space-y-2 text-xs font-medium">
            {l("Question or query", "Pregunta o consulta")}
            <Input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              required
            />
          </label>
          <ProductFields
            action={searchAction}
            values={extra}
            onChange={setExtra}
            exclude={["resourceId", "query"]}
          />
          <Button
            type="submit"
            appearance="gradient"
            loading={search.pending}
            disabled={!searchAction || !query.trim()}
          >
            <Search />
            {l("Find source passages", "Buscar fragmentos fuente")}
          </Button>
        </form>
        <ProductOperationFeedback operation={search} />
        <ProductActionUnavailable action={searchAction} />
        {hits.length ? (
          <ProductSearchResults hits={hits} query={searchedQuery} />
        ) : (
          <ProductEmpty>
            {searchedQuery
              ? l(
                  "No matching source passages",
                  "No hay fragmentos fuente coincidentes",
                )
              : l(
                  "Search results will include the source passage and citation link returned by your backend.",
                  "Los resultados incluirán el fragmento fuente y el enlace de cita devueltos por tu backend.",
                )}
          </ProductEmpty>
        )}
        {search.result &&
          !["search", "knowledge"].includes(search.result.kind) && (
            <ProductResult result={search.result} />
          )}
      </ProductPanel>
      <ProductPanel title={l("Evaluate retrieval", "Evaluar recuperación")}>
        <div className="grid gap-4 sm:grid-cols-2">
          <Select
            label={l("Citation to evaluate", "Cita para evaluar")}
            options={hits.map((hit, index) => ({
              value: hit.id,
              label: `[${index + 1}] ${hit.title}`,
            }))}
            value={selectedHit}
            onValueChange={(value) => {
              setSelectedHit(value);
              setReview(null);
            }}
          />
          <Select
            label={l("Assessment", "Evaluación")}
            value={rating}
            onValueChange={(value) => {
              setRating(value);
              setReview(null);
            }}
            options={[
              { value: "relevant", label: l("Relevant", "Relevante") },
              { value: "incorrect", label: l("Incorrect", "Incorrecta") },
              { value: "outdated", label: l("Outdated", "Desactualizada") },
              {
                value: "access-concern",
                label: l("Access concern", "Problema de acceso"),
              },
            ]}
          />
        </div>
        <div className="my-4">
          <ProductLabeledTextarea
            label={l("Evaluation notes", "Notas de evaluación")}
            value={feedback}
            onChange={(event) => {
              setFeedback(event.target.value);
              setReview(null);
            }}
          />
        </div>
        <ProductFields
          action={evaluateAction}
          values={extra}
          onChange={(value) => {
            setExtra(value);
            setReview(null);
          }}
          exclude={[
            "resourceId",
            "hitId",
            "sourceId",
            "query",
            "rating",
            "feedback",
            "comment",
          ]}
        />
        <div className="mt-4">
          <ProductValidation
            action={evaluateAction}
            values={evaluationValues}
          />
          <Button
            appearance="gradient"
            disabled={
              !evaluateAction ||
              !selectedHit ||
              evaluate.pending ||
              Boolean(invalidProductField(evaluateAction, evaluationValues))
            }
            onClick={() => stage(evaluateAction, evaluationValues, "evaluate")}
          >
            <ThumbsUp />
            {l("Review evaluation", "Revisar evaluación")}
          </Button>
        </div>
        <div className="mt-4">
          <ProductActionUnavailable action={evaluateAction} />
          <ProductOperationFeedback operation={evaluate} />
          <ProductResult result={evaluate.result} />
        </div>
      </ProductPanel>
      {review && (
        <ProductReview
          action={review.action}
          values={review.values}
          pending={ingest.pending || evaluate.pending || remove.pending}
          disabled={
            !reviewSourceCurrent ||
            (review.operation === "delete" && read.pending)
          }
          grantedPermissions={props.connection.grantedPermissions}
          onConfirm={() => {
            void submit();
          }}
          onReject={() => setReview(null)}
        >
          {review.operation === "delete" && review.source && (
            <div className="mb-4 rounded-xl border border-destructive/20 bg-destructive/5 p-4">
              <p className="text-sm font-semibold">{review.source.name}</p>
              <p className="mt-2 text-xs leading-6">
                {l(
                  "This requests removal of this source and its indexed data. Only a reported source deletion marks it as deleted.",
                  "Se solicita eliminar esta fuente y sus datos indexados. Solo se marcará como eliminada cuando el servicio lo reporte.",
                )}
              </p>
              {!reviewSourceCurrent && (
                <p role="alert" className="mt-2 text-xs">
                  {l(
                    "The selected source changed. Refresh and review the current source again.",
                    "La fuente seleccionada cambió. Actualiza y vuelve a revisar la fuente actual.",
                  )}
                </p>
              )}
            </div>
          )}
        </ProductReview>
      )}
    </div>
  );
}

function KnowledgeSourceStatus({ source }: { source: IntegrationRecord }) {
  const { l } = useLanguage();
  const status = productReportedRemoval(source);
  return (
    <ProductStatus
      value={
        status === "deleted"
          ? l(
              "Deleted · reported by service",
              "Eliminada · reportada por el servicio",
            )
          : status === "pending"
            ? l(
                "Deleting · reported by service",
                "Eliminando · reportado por el servicio",
              )
            : status === "failed"
              ? l(
                  "Deletion failed · reported by service",
                  "Eliminación fallida · reportada por el servicio",
                )
              : source.status
      }
    />
  );
}

function KnowledgeRemovalStatus({
  removal,
}: {
  removal: ProductSourceRemoval;
}) {
  const { l } = useLanguage();
  const labels: Record<ProductSourceRemoval["phase"], [string, string]> = {
    submitted: [
      "Submitting deletion request",
      "Enviando solicitud de eliminación",
    ],
    pending: [
      "Deletion pending · reported by service",
      "Eliminación pendiente · reportada por el servicio",
    ],
    "awaiting-status": [
      "Source deletion is not yet reported. Refresh its status.",
      "La eliminación de la fuente aún no ha sido reportada. Actualiza su estado.",
    ],
    deleted: [
      "Source deletion reported by service",
      "Eliminación de fuente reportada por el servicio",
    ],
    failed: [
      "Deletion failed · reported by service",
      "Eliminación fallida · reportada por el servicio",
    ],
    "request-failed": [
      "Deletion request failed; source state is unchanged in this view",
      "La solicitud falló; el estado de la fuente no cambió en esta vista",
    ],
    unconfirmed: [
      "The request outcome is unconfirmed. Refresh to inspect the source.",
      "El resultado de la solicitud no está confirmado. Actualiza para consultar la fuente.",
    ],
  };
  return <p className="text-xs leading-6">{l(...labels[removal.phase])}</p>;
}

"use client";

import { lazy, Suspense, useState } from "react";
import { LocateFixed, MapPin, Route } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import type {
  IntegrationResult,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import type { IntegrationMapRenderer } from "@/lib/integrations/map-renderer";
import {
  findProductAction,
  invalidProductField,
  productActionValues,
  productMapLocations,
} from "./product-model";
import {
  ProductActionUnavailable,
  ProductEmpty,
  ProductFields,
  ProductOperationFeedback,
  ProductPanel,
  ProductResourcePicker,
  ProductResult,
  ProductValidation,
  useProductResources,
} from "./product-ui";

const DemoRouteMap = lazy(() =>
  import("@/components/blocks/route-map").then((module) => ({
    default: module.RouteMap,
  })),
);
type Location = Extract<
  IntegrationResult,
  { kind: "map" }
>["locations"][number];

function CoordinateMap({
  locations,
  coordinates,
  selected,
  onSelect,
}: {
  locations: Location[];
  coordinates?: [number, number][];
  selected: string;
  onSelect: (id: string) => void;
}) {
  const { l } = useLanguage();
  const x = (longitude: number) => (longitude + 180) * 2;
  const y = (latitude: number) => (90 - latitude) * 2;
  const route = (coordinates ?? []).filter(
    ([lng, lat]) =>
      Number.isFinite(lng) &&
      Number.isFinite(lat) &&
      Math.abs(lng) <= 180 &&
      Math.abs(lat) <= 90,
  );
  return (
    <div className="overflow-hidden rounded-xl border border-border bg-linear-to-br from-primary/5 to-surface-subtle">
      <svg
        viewBox="0 0 720 360"
        role="group"
        aria-label={l(
          "Coordinates returned by the connected source",
          "Coordenadas devueltas por la fuente conectada",
        )}
        className="min-h-64 w-full"
      >
        <title>
          {l(
            "Select a location to inspect its coordinates",
            "Selecciona una ubicación para revisar sus coordenadas",
          )}
        </title>
        {[-120, -60, 0, 60, 120].map((lng) => (
          <line
            key={`lng-${lng}`}
            x1={x(lng)}
            x2={x(lng)}
            y1="0"
            y2="360"
            stroke="var(--border)"
            strokeDasharray="3 4"
          />
        ))}
        {[-60, -30, 0, 30, 60].map((lat) => (
          <line
            key={`lat-${lat}`}
            y1={y(lat)}
            y2={y(lat)}
            x1="0"
            x2="720"
            stroke="var(--border)"
            strokeDasharray="3 4"
          />
        ))}
        {route.length > 1 && (
          <polyline
            points={route.map(([lng, lat]) => `${x(lng)},${y(lat)}`).join(" ")}
            stroke="var(--primary)"
            fill="none"
            strokeWidth="2"
          />
        )}
        {locations.map((location, index) => (
          <g
            key={location.id}
            role="button"
            tabIndex={0}
            aria-label={`${location.name}: ${location.latitude}, ${location.longitude}`}
            aria-pressed={selected === location.id}
            onClick={() => onSelect(location.id)}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                onSelect(location.id);
              }
            }}
            className="cursor-pointer outline-none focus-visible:[&_circle]:stroke-[var(--ring)]"
          >
            <circle
              cx={x(location.longitude)}
              cy={y(location.latitude)}
              r={selected === location.id ? 10 : 7}
              fill="var(--primary)"
              stroke="var(--surface)"
              strokeWidth="3"
            />
            <text
              x={x(location.longitude)}
              y={y(location.latitude) - 14}
              textAnchor="middle"
              fontSize="11"
              fill="var(--foreground)"
            >
              {index + 1}
            </text>
          </g>
        ))}
      </svg>
      <p className="border-t border-border px-4 py-3 text-[11px] text-muted-foreground">
        {l(
          "Schematic coordinate view · no external basemap",
          "Vista esquemática de coordenadas · sin mapa base externo",
        )}
      </p>
    </div>
  );
}

export function ProductMapsWorkbench(props: IntegrationWorkbenchProps & { renderMap?: IntegrationMapRenderer }) {
  const { l, number } = useLanguage();
  const operation = useIntegrationOperation(props);
  const resources = useProductResources(props);
  const geocode = findProductAction(props.definition, "geocode");
  const route = findProductAction(props.definition, "route");
  const query = findProductAction(props.definition, "query");
  const [resourceId, setResourceId] = useState(
    props.connection.resourceIds[0] ?? "",
  );
  const [address, setAddress] = useState("");
  const [extra, setExtra] = useState<IntegrationValues>({});
  const [locations, setLocations] = useState<Location[]>([]);
  const [routeResult, setRouteResult] = useState<Extract<
    IntegrationResult,
    { kind: "map" }
  > | null>(null);
  const [selected, setSelected] = useState("");
  const [origin, setOrigin] = useState("");
  const [destination, setDestination] = useState("");
  const [invalidLocations, setInvalidLocations] = useState(false);
  const [showDemo, setShowDemo] = useState(true);
  const geocodeValues = productActionValues(
    geocode,
    { ...extra, address, query: address },
    resourceId,
  );
  const routeValues = productActionValues(
    route,
    { ...extra, origin, destination, from: origin, to: destination },
    resourceId,
  );

  async function run(kind: "query" | "geocode" | "route") {
    const action =
      kind === "query" ? query : kind === "geocode" ? geocode : route;
    if (!action) return;
    const values =
      kind === "route"
        ? routeValues
        : kind === "geocode"
          ? geocodeValues
          : productActionValues(action, extra, resourceId);
    if (invalidProductField(action, values)) return;
    const result = await operation.run(action, values);
    if (result?.kind !== "map") return;
    const valid = productMapLocations(result);
    setInvalidLocations(valid.length !== result.locations.length);
    setLocations((previous) => {
      const merged = new Map(
        (kind === "query" ? [] : previous).map((item) => [item.id, item]),
      );
      valid.forEach((item) => merged.set(item.id, item));
      return [...merged.values()];
    });
    if (valid[0]) {
      setSelected(valid[0].id);
      if (!origin) setOrigin(valid[0].id);
      if (!destination)
        setDestination(
          valid.find((item) => item.id !== (origin || valid[0].id))?.id ?? "",
        );
    }
    if (kind === "route") setRouteResult(result);
  }
  const location = locations.find((item) => item.id === selected);
  const options = locations.map((item) => ({
    value: item.id,
    label: item.name,
  }));

  return (
    <div className="space-y-5">
      <ProductPanel
        title={l("Location workbench", "Espacio de ubicaciones")}
        description={
          props.adapter.mode === "demo"
            ? l(
                "Addresses, locations and routes are local fixtures, including when Google Maps or Mapbox is selected. The demo uses no provider keys, styles or SDK requests.",
                "Direcciones, ubicaciones y rutas son fixtures locales, también al seleccionar Google Maps o Mapbox. La demo no usa claves, estilos ni solicitudes de SDK del proveedor.",
              )
            : l(
                "Resolve addresses and select locations returned by this connection.",
                "Resuelve direcciones y selecciona ubicaciones devueltas por esta conexión.",
              )
        }
      >
        <ProductResourcePicker
          {...resources}
          value={resourceId}
          onChange={(value) => {
            operation.reset();
            setResourceId(value);
            setLocations([]);
            setRouteResult(null);
            setSelected("");
            setOrigin("");
            setDestination("");
          }}
          disabled={operation.pending}
        />
        {query && (
          <div className="mt-4">
            <Button
              variant="outline"
              loading={operation.pending}
              onClick={() => {
                void run("query");
              }}
            >
              {l("Load authorized locations", "Cargar ubicaciones autorizadas")}
            </Button>
          </div>
        )}
        <form
          className="mt-5 space-y-4"
          onSubmit={(event) => {
            event.preventDefault();
            void run("geocode");
          }}
        >
          <label className="block space-y-2 text-xs font-medium">
            {l("Address or place", "Dirección o lugar")}
            <Input
              value={address}
              onChange={(event) => setAddress(event.target.value)}
              placeholder={l(
                "Enter a place to resolve",
                "Introduce un lugar para resolver",
              )}
              required
            />
          </label>
          <ProductFields
            action={geocode}
            values={extra}
            onChange={setExtra}
            exclude={["resourceId", "address", "query"]}
          />
          <ProductValidation action={geocode} values={geocodeValues} />
          <Button
            type="submit"
            appearance="gradient"
            disabled={
              !geocode ||
              !address.trim() ||
              operation.pending ||
              Boolean(invalidProductField(geocode, geocodeValues))
            }
          >
            <LocateFixed />
            {l("Resolve address", "Resolver dirección")}
          </Button>
        </form>
        <div className="mt-4">
          <ProductActionUnavailable action={geocode} />
          <ProductOperationFeedback operation={operation} />
        </div>
      </ProductPanel>
      <div className="grid items-start gap-5 xl:grid-cols-[2fr_1fr]">
        <ProductPanel title={l("Returned locations", "Ubicaciones devueltas")}>
          {locations.length ? (
            <>
              {props.renderMap ? props.renderMap({
                connection: props.connection,
                scope: props.scope,
                locations,
                coordinates: routeResult?.coordinates,
                selectedLocationId: selected,
                onLocationSelect: setSelected,
                fallback: <CoordinateMap locations={locations} coordinates={routeResult?.coordinates} selected={selected} onSelect={setSelected} />,
              }) : <CoordinateMap locations={locations} coordinates={routeResult?.coordinates} selected={selected} onSelect={setSelected} />}
              <ul className="mt-4 grid gap-2 sm:grid-cols-2">
                {locations.map((item, index) => (
                  <li key={item.id}>
                    <Button
                      variant={selected === item.id ? "secondary" : "outline"}
                      className="h-auto min-h-11 w-full justify-start whitespace-normal py-3 text-left"
                      onClick={() => setSelected(item.id)}
                      aria-pressed={selected === item.id}
                    >
                      <MapPin />
                      <span>
                        {index + 1}. {item.name}
                      </span>
                    </Button>
                  </li>
                ))}
              </ul>
            </>
          ) : (
            <ProductEmpty>
              {l(
                "Load authorized locations or resolve an address to begin.",
                "Carga ubicaciones autorizadas o resuelve una dirección para comenzar.",
              )}
            </ProductEmpty>
          )}
          {invalidLocations && (
            <p
              role="alert"
              className="mt-3 text-xs text-destructive-foreground"
            >
              {l(
                "Some returned locations had missing IDs or invalid coordinates and were omitted.",
                "Se omitieron ubicaciones con IDs ausentes o coordenadas inválidas.",
              )}
            </p>
          )}
          {location && (
            <dl className="mt-4 grid gap-3 rounded-xl bg-surface-subtle p-4 text-xs sm:grid-cols-2">
              <div>
                <dt className="text-muted-foreground">
                  {l("Location", "Ubicación")}
                </dt>
                <dd className="mt-1 font-medium">{location.name}</dd>
              </div>
              <div>
                <dt className="text-muted-foreground">ID</dt>
                <dd className="mt-1 wrap-break-word">{location.id}</dd>
              </div>
              <div>
                <dt className="text-muted-foreground">
                  {l("Latitude", "Latitud")}
                </dt>
                <dd className="mt-1">
                  {number(location.latitude, { maximumFractionDigits: 6 })}
                </dd>
              </div>
              <div>
                <dt className="text-muted-foreground">
                  {l("Longitude", "Longitud")}
                </dt>
                <dd className="mt-1">
                  {number(location.longitude, { maximumFractionDigits: 6 })}
                </dd>
              </div>
            </dl>
          )}
        </ProductPanel>
        <ProductPanel title={l("Route request", "Solicitud de ruta")}>
          <div className="space-y-4">
            <Select
              label={l("Origin", "Origen")}
              options={options}
              value={origin}
              onValueChange={(value) => {
                setOrigin(value);
                setRouteResult(null);
              }}
            />
            <Select
              label={l("Destination", "Destino")}
              options={options}
              value={destination}
              onValueChange={(value) => {
                setDestination(value);
                setRouteResult(null);
              }}
            />
            <ProductFields
              action={route}
              values={extra}
              onChange={(value) => {
                setExtra(value);
                setRouteResult(null);
              }}
              exclude={["resourceId", "origin", "destination", "from", "to"]}
            />
            <ProductValidation action={route} values={routeValues} />
            <Button
              appearance="gradient"
              disabled={
                !route ||
                operation.pending ||
                !origin ||
                !destination ||
                origin === destination ||
                Boolean(invalidProductField(route, routeValues))
              }
              onClick={() => {
                void run("route");
              }}
            >
              <Route />
              {l("Request route", "Solicitar ruta")}
            </Button>
            <ProductActionUnavailable action={route} />
            {routeResult && (
              <p
                role="status"
                className="text-xs leading-6 text-muted-foreground"
              >
                {routeResult.coordinates?.length
                  ? props.adapter.mode === "demo"
                    ? l(
                        "Demonstration route geometry. This is not a live directions response.",
                        "Geometría de ruta de demostración. No es una respuesta de indicaciones en vivo.",
                      )
                    : l(
                        "Displaying route geometry returned by your backend.",
                        "Se muestra la geometría de ruta devuelta por tu backend.",
                      )
                  : l(
                      "The backend returned locations without route geometry.",
                      "El backend devolvió ubicaciones sin geometría de ruta.",
                    )}
              </p>
            )}
          </div>
        </ProductPanel>
      </div>
      {operation.result && operation.result.kind !== "map" && (
        <ProductPanel title={l("Source response", "Respuesta de la fuente")}>
          <ProductResult result={operation.result} />
        </ProductPanel>
      )}
      {props.adapter.mode === "demo" && (
        <ProductPanel
          title={l(
            "Aureform route-map example",
            "Ejemplo de mapa de rutas de Aureform",
          )}
          description={l(
            "This existing RouteMap uses fixed demonstration routes, separately from the locations above.",
            "Este RouteMap existente usa rutas fijas de demostración, separadas de las ubicaciones anteriores.",
          )}
        >
          <Button
            variant="outline"
            onClick={() => setShowDemo((value) => !value)}
          >
            {showDemo
              ? l("Hide example", "Ocultar ejemplo")
              : l("Show route-map example", "Mostrar ejemplo de mapa")}
          </Button>
          {showDemo && (
            <div className="mt-4">
              <Suspense
                fallback={
                  <ProductEmpty>
                    {l("Loading map example…", "Cargando ejemplo de mapa…")}
                  </ProductEmpty>
                }
              >
                <DemoRouteMap
                  label={l(
                    "Fixed demonstration shipment routes",
                    "Rutas fijas de envíos de demostración",
                  )}
                />
              </Suspense>
            </div>
          )}
        </ProductPanel>
      )}
    </div>
  );
}

import type {
  IntegrationAction,
  IntegrationDefinition,
  IntegrationField,
  IntegrationOperationKind,
  IntegrationRecord,
  IntegrationResult,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "../../lib/integrations/contracts";
import type { DataTableQuery } from "../../lib/data-query";

export function findProductAction(
  definition: IntegrationDefinition,
  ...kinds: IntegrationOperationKind[]
) {
  for (const kind of kinds) {
    const action = definition.actions.find((item) => item.kind === kind);
    if (action) return action;
  }
  return undefined;
}

/** A configuration or permission change discards drafts tied to the old scope. */
export function productScopeKey({
  definition,
  connection,
  scope,
  adapter,
}: IntegrationWorkbenchProps) {
  return JSON.stringify([
    adapter.mode,
    definition.id,
    connection.id,
    connection.providerOptionId,
    connection.workspaceId,
    scope.workspaceId,
    connection.revision,
    connection.status,
    [...connection.resourceIds].sort(),
    [...connection.grantedPermissions].sort(),
  ]);
}

export function defaultActionValues(
  action?: IntegrationAction,
): IntegrationValues {
  return Object.fromEntries(
    (action?.fields ?? []).map((field) => [
      field.id,
      field.type === "toggle"
        ? false
        : field.type === "select"
          ? (field.options?.[0]?.value ?? "")
          : "",
    ]),
  );
}

/** A create recipe must never reuse the selected source record as its target. */
export function productRecordNeedsTarget(action?: IntegrationAction) {
  return (
    action?.kind === "update-record" ||
    (action?.kind === "save-record" &&
      action.fields.some(
        (field) => ["recordId", "id"].includes(field.id) && field.required,
      ))
  );
}

/** Demo reads can start immediately; consumer references remain explicit inputs. */
export function productReadDefaults(
  action: IntegrationAction | undefined,
  props: IntegrationWorkbenchProps,
): IntegrationValues {
  const values = defaultActionValues(action);
  if (props.adapter.mode !== "demo") return values;
  const start = new Date();
  start.setUTCHours(0, 0, 0, 0);
  const end = new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000);
  for (const field of action?.fields ?? []) {
    if (!field.required || field.type !== "text") continue;
    if (field.id === "startAt") values[field.id] = start.toISOString();
    else if (field.id === "endAt") values[field.id] = end.toISOString();
    else if (/(?:Id|Ref)$/.test(field.id))
      values[field.id] = props.connection.resourceIds[0] ?? "";
  }
  return values;
}

const resourceFields = new Set([
  "resourceId",
  "resource",
  "sourceId",
  "collectionId",
  "tableId",
  "indexId",
  "channelId",
  "repositoryId",
  "projectId",
  "databaseId",
  "siteId",
]);

/** Explicit values win. A resource binding is always a consumer-authorized ID. */
export function productActionValues(
  action: IntegrationAction | undefined,
  values: IntegrationValues,
  resourceId = "",
): IntegrationValues {
  const output = { ...defaultActionValues(action), ...values };
  if (resourceId) {
    output.resourceId = resourceId;
    for (const field of action?.fields ?? []) {
      if (resourceFields.has(field.id) && !output[field.id]) {
        output[field.id] = resourceId;
      }
    }
  }
  return output;
}

export function invalidProductField(
  action: Pick<IntegrationAction, "fields"> | undefined,
  values: IntegrationValues,
): IntegrationField | undefined {
  return action?.fields.find((field) => {
    const value = values[field.id];
    const empty =
      value === undefined ||
      (typeof value === "string" && !value.trim()) ||
      (Array.isArray(value) && value.length === 0);
    if (empty) return field.required === true;
    if (field.type === "number") {
      return !Number.isFinite(
        typeof value === "number" ? value : Number(value),
      );
    }
    if (field.type === "toggle") return typeof value !== "boolean";
    if (field.type === "select") {
      return !field.options?.some((option) => option.value === value);
    }
    return false;
  });
}

export function parseProductArguments(
  source: string,
): { ok: true; json: string } | { ok: false } {
  function valid(value: unknown, depth = 0): boolean {
    if (depth > 20) return false;
    if (
      value === null ||
      typeof value === "string" ||
      typeof value === "boolean"
    )
      return true;
    if (typeof value === "number") return Number.isFinite(value);
    if (Array.isArray(value))
      return value.every((item) => valid(item, depth + 1));
    if (!value || typeof value !== "object") return false;
    return Object.entries(value).every(
      ([key, item]) =>
        !["__proto__", "constructor", "prototype"].includes(key) &&
        valid(item, depth + 1),
    );
  }
  try {
    const value = JSON.parse(source);
    if (
      !value ||
      typeof value !== "object" ||
      Array.isArray(value) ||
      !valid(value)
    )
      return { ok: false };
    return { ok: true, json: JSON.stringify(value) };
  } catch {
    return { ok: false };
  }
}

/** The backend applies filters/sorting/page boundaries; the UI never re-pages results. */
export function productQueryValues(
  query: DataTableQuery,
  resourceId = "",
): IntegrationValues {
  const sort = query.sorting[0];
  const status = query.filters.find((filter) => filter.id === "status");
  const filterValue = status?.value;
  return {
    resourceId,
    query: query.search,
    search: query.search,
    filter: typeof filterValue === "string" ? filterValue : "",
    status: typeof filterValue === "string" ? filterValue : "",
    page: query.pagination.pageIndex,
    pageNumber: query.pagination.pageIndex + 1,
    pageIndex: query.pagination.pageIndex,
    pageSize: query.pagination.pageSize,
    limit: query.pagination.pageSize,
    offset: query.pagination.pageIndex * query.pagination.pageSize,
    sort: sort?.id ?? "",
    order: sort?.desc ? "desc" : "asc",
    direction: sort?.desc ? "desc" : "asc",
    filters: JSON.stringify(query.filters),
    sorting: JSON.stringify(query.sorting),
    queryState: JSON.stringify(query),
  };
}

export function mergeProductRecords(
  previous: readonly IntegrationRecord[],
  incoming: readonly IntegrationRecord[],
) {
  const records = new Map(previous.map((record) => [record.id, record]));
  for (const record of incoming) {
    if (!record.id) continue;
    const current = records.get(record.id);
    if (
      current &&
      Number.isFinite(Date.parse(current.updatedAt)) &&
      Number.isFinite(Date.parse(record.updatedAt)) &&
      Date.parse(record.updatedAt) < Date.parse(current.updatedAt)
    ) {
      continue;
    }
    records.set(record.id, record);
  }
  return [...records.values()];
}

export function optimisticProductRecord(
  record: IntegrationRecord,
  values: IntegrationValues,
  marker: string,
): IntegrationRecord {
  return {
    ...record,
    name: typeof values.name === "string" ? values.name : record.name,
    description:
      typeof values.description === "string"
        ? values.description
        : record.description,
    status: typeof values.status === "string" ? values.status : record.status,
    updatedAt: marker,
  };
}

/** Roll back only this mutation, never a newer query or another acknowledged write. */
export function rollbackProductRecord(
  records: readonly IntegrationRecord[],
  original: IntegrationRecord,
  marker: string,
) {
  return records.map((record) =>
    record.id === original.id && record.updatedAt === marker
      ? original
      : record,
  );
}

export function parseProductFields(
  source: string,
):
  | { ok: true; values: IntegrationValues }
  | { ok: false; reason: "json" | "values" } {
  let value: unknown;
  try {
    value = JSON.parse(source);
  } catch {
    return { ok: false, reason: "json" };
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return { ok: false, reason: "values" };
  }
  const entries = Object.entries(value);
  if (
    entries.some(
      ([key, item]) =>
        ["__proto__", "constructor", "prototype"].includes(key) ||
        !(
          typeof item === "string" ||
          typeof item === "boolean" ||
          (typeof item === "number" && Number.isFinite(item)) ||
          (Array.isArray(item) &&
            item.every((part) => typeof part === "string"))
        ),
    )
  ) {
    return { ok: false, reason: "values" };
  }
  return { ok: true, values: Object.fromEntries(entries) };
}

export function safeProductUrl(value?: string) {
  if (!value) return undefined;
  if (
    value.startsWith("/") &&
    !value.startsWith("//") &&
    !value.includes("\\")
  ) {
    return value;
  }
  try {
    const url = new URL(value);
    return ["https:", "http:"].includes(url.protocol) &&
      !url.username &&
      !url.password
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
}

export function productSearchSegments(text: string, query: string) {
  const term = query.trim();
  if (!term) return [{ text, match: false }];
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return text
    .split(new RegExp(`(${escaped})`, "ig"))
    .filter(Boolean)
    .map((part) => ({
      text: part,
      match: part.toLocaleLowerCase() === term.toLocaleLowerCase(),
    }));
}

export function productMapLocations(
  result: Extract<IntegrationResult, { kind: "map" }>,
) {
  const seen = new Set<string>();
  return result.locations.filter((location) => {
    if (
      !location.id ||
      seen.has(location.id) ||
      !Number.isFinite(location.latitude) ||
      !Number.isFinite(location.longitude) ||
      Math.abs(location.latitude) > 90 ||
      Math.abs(location.longitude) > 180
    ) {
      return false;
    }
    seen.add(location.id);
    return true;
  });
}

export type ProductFieldMapping = { source: string; target: string };
export function validProductMapping(mapping: readonly ProductFieldMapping[]) {
  const targets = new Set<string>();
  return (
    mapping.length > 0 &&
    mapping.every(({ source, target }) => {
      if (
        !source.trim() ||
        !target.trim() ||
        targets.has(target) ||
        ["__proto__", "constructor", "prototype"].includes(target)
      ) {
        return false;
      }
      targets.add(target);
      return true;
    })
  );
}

export function mapProductRecord(
  record: IntegrationRecord,
  mapping: readonly ProductFieldMapping[],
): IntegrationValues {
  const fields: IntegrationValues = {
    ...record.fields,
    id: record.id,
    name: record.name,
    title: record.name,
    status: record.status,
    description: record.description,
    type: record.type,
    updatedAt: record.updatedAt,
  };
  return Object.fromEntries(
    mapping
      .filter(
        ({ source, target }) =>
          source in fields &&
          !["__proto__", "constructor", "prototype"].includes(target),
      )
      .map(({ source, target }) => [target, fields[source]]),
  );
}

/** Only declarative primitive input fields are read; schema code is never evaluated. */
export function productToolFields(
  record?: IntegrationRecord,
): IntegrationField[] {
  const source = record?.fields?.inputSchema ?? record?.fields?.schema;
  if (typeof source !== "string" || source.length > 50_000) return [];
  try {
    const schema = JSON.parse(source);
    if (
      !schema ||
      typeof schema !== "object" ||
      !schema.properties ||
      typeof schema.properties !== "object"
    )
      return [];
    const required = new Set(
      Array.isArray(schema.required) ? schema.required : [],
    );
    return Object.entries(schema.properties)
      .filter(([id]) => !["__proto__", "constructor", "prototype"].includes(id))
      .flatMap(([id, value]) => {
        if (!value || typeof value !== "object") return [];
        const property = value as {
          title?: string;
          description?: string;
          type?: string;
          enum?: unknown[];
        };
        if (
          !["string", "number", "integer", "boolean"].includes(
            property.type ?? "",
          )
        )
          return [];
        const title = typeof property.title === "string" ? property.title : id;
        const options = Array.isArray(property.enum)
          ? property.enum
              .filter((item): item is string => typeof item === "string")
              .map((item) => ({ value: item, label: { en: item, es: item } }))
          : [];
        return [
          {
            id,
            label: { en: title, es: title },
            description:
              typeof property.description === "string"
                ? { en: property.description, es: property.description }
                : undefined,
            type: options.length
              ? "select"
              : property.type === "boolean"
                ? "toggle"
                : ["number", "integer"].includes(property.type ?? "")
                  ? "number"
                  : "text",
            options: options.length ? options : undefined,
            required: required.has(id),
          } satisfies IntegrationField,
        ];
      });
  } catch {
    return [];
  }
}

"use client";

import { useEffect, useRef, useState } from "react";
import { ChevronLeft, ChevronRight, RefreshCw, Search } from "lucide-react";
