                lastAssistant.current = "";
                setMessages([]);
                setPrompt("");
                setError("");
                setClearOpen(false);
              }}
            >
              {l("Start fresh", "Empezar de nuevo")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
