const completionSchema = z.union([flowSchema, actionSchema]);
const enrollmentSchema = z.object({
  kind: z.literal("mfa-enrollment"),
  enrollmentId: id,
  secret: z
    .string()
    .min(16)
    .max(128)
    .regex(/^[A-Z2-7]+$/),
