  resendVerification: z.object({ email, challengeId: id.optional() }),
  getSession: empty,
  logout: empty,
  getIdentity: empty,
  updateProfile: z.object({ name }),
  changePassword: z.object({ currentPassword: password, newPassword }),
  enrollMfa: z.object({
    password: password.optional(),
