export type AuthWorkflowErrorCode = (typeof AUTH_WORKFLOW_ERROR_CODES)[number];
export class AuthWorkflowError extends Error {
  readonly code: AuthWorkflowErrorCode;
  readonly retryAfterSeconds?: number;
