    signUp: (request) => {
      user = {
        ...user,
        name: request.name,
        email: request.email,
        emailVerified: false,
      };
      session = null;
      sessions = [];
      const challengeId = nextId("email-challenge");
      challenges.set(challengeId, {
        kind: "email",
        email: request.email,
        name: request.name,
      });
      return {
        kind: "verification-required",
        challengeId,
        email: request.email,
      };
