      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient))
        throw new IntegrationError("validation");
      return {
        kind: "delivery",
        delivery: {
          id: `demo-delivery-${state.events.length + 1}`,
