      };
    case "run-agent":
    case "execute-tool": {
      const id = `demo-tool-${state.tools.size + 1}`;
      const run: IntegrationToolRun = {
        id,
        name: inputText("tool", inputText("name", "create_document_draft")),
        state: "approval-required",
        input: values,
        approvalId: `approval-${id}`,
        ...(kind === "run-agent"
          ? {
              handoffs: [
                {
                  id: `${id}:handoff`,
                  from: "Demo coordinator",
