function parsed<T>(schema: z.ZodType<T>, input: unknown): T {
  const result = schema.safeParse(input);
  if (!result.success) throw new IntegrationError("provider-error");
  return result.data;
}
export const parseIntegrationResult = (input: unknown): IntegrationResult =>
  parsed(integrationResultSchema, input);
export const parseIntegrationResource = (input: unknown): IntegrationResource =>
  parsed(integrationResourceSchema, input);
export const parseIntegrationEvent = (input: unknown): IntegrationEvent =>
  parsed(integrationEventSchema, input);
export function validateIntegrationScope(scope: IntegrationScope) {
  if (!id.safeParse(scope.workspaceId).success)
    throw new IntegrationError("validation");
  if (scope.signal?.aborted) throw new IntegrationError("cancelled");
}
export function parseIntegrationConnection(
  input: unknown,
  definition: IntegrationDefinition,
  scope: IntegrationScope,
): IntegrationConnection {
  const connection = parsed(integrationConnectionSchema, input);
  if (
    connection.integrationId !== definition.id ||
    connection.workspaceId !== scope.workspaceId ||
    !definition.options.some(
      (option) => option.id === connection.providerOptionId,
    ) ||
    connection.grantedPermissions.some(
      (permission) =>
        !definition.permissions.some((allowed) => allowed.id === permission),
    ) ||
    new Set(connection.grantedPermissions).size !==
      connection.grantedPermissions.length ||
    new Set(connection.resourceIds).size !== connection.resourceIds.length
  )
    throw new IntegrationError("provider-error");
  try {
    validateIntegrationFields(
      definition.configurationFields,
      connection.configuration,
      false,
    );
  } catch {
    throw new IntegrationError("provider-error");
  }
  return connection;
}

export function validateIntegrationFields(
  fields: IntegrationDefinition["configurationFields"],
  values: IntegrationValues,
  requireAll = true,
) {
  if (!integrationValuesSchema.safeParse(values).success)
    throw new IntegrationError("validation");
  for (const key of Object.keys(values))
    if (!fields.some((field) => field.id === key))
      throw new IntegrationError("validation");
  for (const field of fields) {
    const input = values[field.id];
    if (
      requireAll &&
      field.required &&
      (input === undefined ||
        (typeof input === "string" && !input.trim()) ||
        (Array.isArray(input) && !input.length))
    )
      throw new IntegrationError("validation");
    if (input === undefined || input === "") continue;
    if (
      field.type === "number" &&
      (typeof input !== "number" || !Number.isFinite(input))
    )
      throw new IntegrationError("validation");
    if (field.type === "toggle" && typeof input !== "boolean")
      throw new IntegrationError("validation");
    if (
      ["text", "url", "select"].includes(field.type) &&
      typeof input !== "string"
    )
      throw new IntegrationError("validation");
    if (
      field.type === "url" &&
      typeof input === "string" &&
      !isPresentationUrl(input)
    )
      throw new IntegrationError("validation");
    if (
      field.type === "select" &&
      !field.options?.some((option) => option.value === input)
    )
      throw new IntegrationError("validation");
  }
}

const selection = z
  .array(id)
  .max(500)
  .refine((ids) => new Set(ids).size === ids.length);
export function validateIntegrationSelection(
  definition: IntegrationDefinition,
  permissions: string[],
  resourceIds: string[],
  requirePermissions = true,
) {
  if (
    !selection.safeParse(permissions).success ||
    !selection.safeParse(resourceIds).success ||
    permissions.some(
      (permission) =>
        !definition.permissions.some((allowed) => allowed.id === permission),
    ) ||
    (requirePermissions &&
      definition.permissions.some(
        (permission) =>
          permission.required && !permissions.includes(permission.id),
      ))
  )
    throw new IntegrationError("validation");
}

export function parseIntegrationUpdate(
  input: unknown,
  definition: IntegrationDefinition,
  connectionId: string,
  scope: IntegrationScope,
): IntegrationUpdate {
  validateIntegrationScope(scope);
  if (!input || typeof input !== "object" || !("kind" in input))
    throw new IntegrationError("provider-error");
  if (input.kind === "result" && "result" in input)
    return { kind: "result", result: parseIntegrationResult(input.result) };
  if (input.kind === "connection" && "connection" in input) {
    const connection = parseIntegrationConnection(
      input.connection,
      definition,
      scope,
    );
    if (connection.id !== connectionId)
      throw new IntegrationError("provider-error");
    return { kind: "connection", connection };
  }
  if (input.kind === "presence" && "members" in input) {
    const schema = z
      .array(
        z.object({
          id,
          name: z.string().min(1).max(160),
          state: z.enum(["online", "away", "editing"]),
          avatarUrl: url.optional(),
        }),
      )
      .max(1000)
      .refine(
        (members) =>
          new Set(members.map((member) => member.id)).size === members.length,
      );
    return { kind: "presence", members: parsed(schema, input.members) };
  }
  throw new IntegrationError("provider-error");
}

import type { ProductImage } from "@/lib/commerce";

export const MAX_PRODUCT_IMAGES = 6;
export const MAX_PRODUCT_IMAGE_BYTES = 8 * 1024 * 1024;
export const MAX_PRODUCT_IMAGE_EDGE = 900;
export const MAX_PRODUCT_IMAGE_SOURCE_CHARS = 1_000_000;
export const PRODUCT_IMAGE_ACCEPT = "image/png,image/jpeg,image/webp";
const TARGET_SOURCE_CHARS = 220_000;
const MAX_DECODED_EDGE = 8192;
const MAX_DECODED_PIXELS = 24_000_000;

export type ProductImageErrorCode =
  | "unsupported"
  | "empty"
  | "too-large"
  | "signature"
  | "dimensions"
  | "decode"
  | "encode"
  | "unsafe-source"
  | "aborted";

export class ProductImageError extends Error {
  readonly code: ProductImageErrorCode;

  constructor(code: ProductImageErrorCode) {
    super(code);
    this.name = "ProductImageError";
    this.code = code;
  }
}

export type ProductCropAspect =
  "original" | "square" | "portrait" | "landscape";
export type ProductCropSettings = {
  aspect: ProductCropAspect;
  zoom: number;
  rotation: 0 | 90 | 180 | 270;
  offsetX: number;
  offsetY: number;
};

export const defaultProductCrop: ProductCropSettings = {
  aspect: "original",
  zoom: 1,
  rotation: 0,
  offsetX: 0,
  offsetY: 0,
};

export function validateProductImageFile(file: Pick<File, "size" | "type">) {
  if (!["image/png", "image/jpeg", "image/webp"].includes(file.type))
    throw new ProductImageError("unsupported");
  if (!Number.isFinite(file.size) || file.size <= 0)
    throw new ProductImageError("empty");
  if (file.size > MAX_PRODUCT_IMAGE_BYTES)
    throw new ProductImageError("too-large");
}

/** Check the actual container as well as the browser-supplied MIME type. */
export function hasProductRasterSignature(bytes: Uint8Array, mime: string) {
  if (mime === "image/png") {
    return [137, 80, 78, 71, 13, 10, 26, 10].every(
      (byte, index) => bytes[index] === byte,
    );
  }
  if (mime === "image/jpeg")
    return bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255;
  if (mime === "image/webp") {
    return (
      bytes.length >= 12 &&
      [82, 73, 70, 70].every((byte, index) => bytes[index] === byte) &&
      [87, 69, 66, 80].every((byte, index) => bytes[index + 8] === byte)
    );
  }
  return false;
}

export function validateProductRasterDimensions(width: number, height: number) {
  if (
    !Number.isInteger(width) ||
    !Number.isInteger(height) ||
    width < 1 ||
    height < 1 ||
    width > MAX_DECODED_EDGE ||
    height > MAX_DECODED_EDGE ||
    width * height > MAX_DECODED_PIXELS
  ) {
    throw new ProductImageError("dimensions");
  }
}

export function fitProductRaster(
  width: number,
  height: number,
  maxEdge = MAX_PRODUCT_IMAGE_EDGE,
) {
  if (
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width <= 0 ||
    height <= 0 ||
    !Number.isFinite(maxEdge) ||
    maxEdge < 1
  ) {
    throw new ProductImageError("dimensions");
  }
  const edge = Math.min(MAX_PRODUCT_IMAGE_EDGE, Math.floor(maxEdge));
  const scale = Math.min(1, edge / Math.max(width, height));
  return {
    width: Math.max(1, Math.round(width * scale)),
    height: Math.max(1, Math.round(height * scale)),
  };
}

const clamp = (value: number, min: number, max: number, fallback: number) =>
  Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;

/** Coordinates are in the rotated source, before output downsampling. */
export function getProductCropGeometry(
  width: number,
  height: number,
  settings: ProductCropSettings,
  maxEdge = MAX_PRODUCT_IMAGE_EDGE,
) {
  validateProductRasterDimensions(width, height);
  const rotation = [0, 90, 180, 270].includes(settings.rotation)
    ? settings.rotation
    : 0;
  const sideways = rotation === 90 || rotation === 270;
  const rotatedWidth = sideways ? height : width;
  const rotatedHeight = sideways ? width : height;
  const ratio =
    settings.aspect === "square"
      ? 1
      : settings.aspect === "portrait"
        ? 4 / 5
        : settings.aspect === "landscape"
          ? 4 / 3
          : rotatedWidth / rotatedHeight;
  const zoom = clamp(settings.zoom, 1, 3, 1);
  const cropWidth = Math.min(rotatedWidth, rotatedHeight * ratio) / zoom;
  const cropHeight = Math.min(rotatedHeight, rotatedWidth / ratio) / zoom;
  const x =
    ((rotatedWidth - cropWidth) * (clamp(settings.offsetX, -1, 1, 0) + 1)) / 2;
  const y =
    ((rotatedHeight - cropHeight) * (clamp(settings.offsetY, -1, 1, 0) + 1)) /
    2;
  return {
    rotation,
    rotatedWidth,
    rotatedHeight,
    x,
    y,
    cropWidth,
    cropHeight,
    ...fitProductRaster(cropWidth, cropHeight, maxEdge),
  };
}

/** Only prepared local rasters enter a canvas; remote and SVG sources never do. */
export function isEditableProductRaster(src: string) {
  return (
    src.length <= MAX_PRODUCT_IMAGE_SOURCE_CHARS &&
    /^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(src)
  );
}

